-- 005_result_analysis.sql
-- Xtreme ExamX: detailed result analysis + RAS scoring fix
-- Run AFTER 002 and 003/004.

ALTER TABLE public.questions ADD COLUMN IF NOT EXISTS explanation TEXT;

-- Store the explanations from the uploaded RAS Prelims Test 1 content.
UPDATE public.questions q SET explanation = v.explanation
FROM (VALUES
('राजस्थान की रियासतों के प्रशासनिक एवं सामाजिक इतिहास के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. जयपुर राज्य में ''मुसाहिब'' (दीवान) प्रशासन का सर्वोच्च अधिकारी होता था।<br>B. मारवाड़ राज्य में सामंतों की चार श्रेणियां—राजवी, सरदार, मुत्सद्दी और गनायत थीं।<br>C. बीकानेर में ''कागद'' नामक अभिलेख भूमि अनुदानों से संबंधित दस्तावेज थे।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'मारवाड़ में सामंतों की श्रेणियों में राजवी (राजपरिवार के निकट सम्बन्धी), सरदार, गनायत और मुत्सद्दी प्रमुख थे। जयपुर में मुसाहिब प्रधानमंत्री/सर्वोच्च दीवान का पद था और बीकानेर में भूमि व जागीर आदेशों को ''कागद'' अथवा परवाना कहा जाता था। तीनों कथन ऐतिहासिक रूप से सत्य हैं।'),
('भारतीय संविधान के अनुच्छेद 243-I एवं 243-Y के अंतर्गत गठित राज्य वित्त आयोग (SFC) के संबंध में असत्य कथन चुनिए:', 'संविधान के अनुच्छेद 243-I(4) के अनुसार, राज्यपाल का यह संवैधानिक दायित्व है कि वह राज्य वित्त आयोग की प्रत्येक सिफारिश और उस पर की गई कार्यवाही के स्पष्टीकारक ज्ञापन (Action Taken Report) को राज्य विधानमंडल के समक्ष प्रस्तुत करवाए।'),
('राजस्थान आर्थिक समीक्षा एवं नवीनतम आंकड़ों के संदर्भ में ''सकल राज्य मूल्य वर्धन'' (GSVA) में प्रचलित मूल्यों पर विभिन्न क्षेत्रों के योगदान का सही घटता क्रम (Descending Order) कौन सा है?', 'राजस्थान की अर्थव्यवस्था में प्रचलित मूल्यों पर GSVA का मानक क्रम: सेवा क्षेत्र (सर्वाधिक ~43-44%) > कृषि एवं संबद्ध क्षेत्र (~27-28%) > उद्योग क्षेत्र (~27%) रहता है।'),
('भारतीय अंतरिक्ष अनुसंधान संगठन (ISRO) तथा वैश्विक अंतरिक्ष अभियानों के संदर्भ में निम्नलिखित युग्मों पर विचार कीजिए:<br><br>1. आदित्य-L1 : सूर्य-पृथ्वी L1 लैग्रेंज बिंदु के चारों ओर प्रभामंडल कक्षा (Halo Orbit)<br>2. निसार (NISAR) : ISRO और ESA का संयुक्त डुअल-फ्रीक्वेंसी सिंथेटिक अपर्चर रडार मिशन<br>3. एक्सपोसेट (XPoSat) : ब्रह्मांडीय स्रोतों से एक्स-रे उत्सर्जन के ध्रुवीकरण का अध्ययन<br><br>उपर्युक्त में से कौन सा/से युग्म सही सुमेलित है/हैं?', 'निसार (NISAR) नासा (NASA) और इसरो (ISRO) का संयुक्त मिशन है, न कि ESA का। अतः युग्म 2 गलत है। आदित्य-L1 और XPoSat पूर्णतः सही सुमेलित हैं।'),
('एक थैले में 4 लाल, 5 सफेद और 6 काली गेंदें हैं। यदि यादृच्छिक रूप से बिना प्रतिस्थापन के तीन गेंदें निकाली जाती हैं, तो कम से कम एक लाल गेंद प्राप्त होने की प्रायिकता (Probability) क्या होगी?', 'कुल गेंदें = 15। 3 गेंदों का चयन = $^{15}C_3 = \frac{15 \times 14 \times 13}{3 \times 2 \times 1} = 455$। कोई भी लाल गेंद न होने के तरीके ($^{11}C_3$) = $\frac{11 \times 10 \times 9}{6} = 165$। अतः कम से कम एक लाल गेंद होने की प्रायिकता = $1 - \frac{165}{455} = \frac{290}{455} = \frac{58}{91}$।'),
('राजस्थान सार्वजनिक परीक्षा (भर्ती में अनुचित साधनों की रोकथाम के अध्युपाय) अधिनियम, 2022 एवं इसके संशोधन अधिनियम, 2023 के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. अनुचित साधनों का उपयोग करने वाले परीक्षार्थी को अधिकतम 3 वर्ष तक का कारावास और न्यूनतम 1 लाख रुपये का जुर्माना हो सकता है।<br>B. संगठित रूप से पेपर लीक करने वाले किसी भी व्यक्ति या एजेंसी को आजीवन कारावास और 10 करोड़ रुपये तक के जुर्माने का प्रावधान किया गया है।<br>C. अपराध में संलिप्त दोषियों की संपत्ति कुर्क करने एवं जब्त करने का अधिकार सक्षम प्राधिकारी को दिया गया है।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'राजस्थान सार्वजनिक परीक्षा (अनुचित साधनों की रोकथाम) अधिनियम, 2022 तथा 2023 के संशोधनों के तहत परीक्षार्थी के लिए 3 वर्ष तक कारावास व ₹1 लाख जुर्माना तथा संगठित गिरोह/एजेंसियों के लिए 10 वर्ष से आजीवन कारावास और ₹10 लाख से ₹10 करोड़ तक के जुर्माने व संपत्ति कुर्की के सख्त प्रावधान किए गए हैं।'),
('सूची-I (राजस्थान के पुरातात्विक स्थल) को सूची-II (संबंधित नदी/उत्खननकर्ता) से सुमेलित कीजिए:<br><br><table style=''width:100%; border-collapse: collapse; margin-top:5px;'' border=''1''><tr><th>सूची-I (स्थल)</th><th>सूची-II (विशेषता/नदी)</th></tr><tr><td>A. बागोर</td><td>i. बनास की सहायक कोठारी नदी</td></tr><tr><td>B. गणेश्वर</td><td>ii. कांतली नदी (ताम्र संचयी संस्कृति)</td></tr><tr><td>C. गिलूण्ड</td><td>iii. बनास नदी घाटी</td></tr><tr><td>D. सुनारी</td><td>iv. कांतली नदी घाटी (लोहयुगीन भट्ठियाँ)</td></tr></table>', 'बागोर भीलवाड़ा में कोठारी नदी के तट पर स्थित मध्यपाषाण कालीन स्थल है; गणेश्वर (नीम का थाना) कांतली नदी पर ताम्रयुगीन स्थल है; गिलूण्ड (राजसमंद) बनास घाटी की संस्कृति है; सुनारी (झुंझुनूं) से प्राचीनतम लोहे गलाने की भट्ठियां मिली हैं।'),
('मध्यकालीन राजस्थान की प्रशासनिक व्यवस्था के संदर्भ में निम्नलिखित पदों एवं उनके कार्यों का कौन सा युग्म सही सुमेलित <strong>नहीं</strong> है?', 'कोतवाल मध्यकालीन राजस्थान में नगर/दुर्ग की सुरक्षा, शांति व्यवस्था और नागरिक प्रशासन का प्रमुख होता था, न कि ग्रामीण भू-राजस्व का। ग्रामीण स्तर पर भू-राजस्व का कार्य पटवारी/चौधरी/पटेल आदि करते थे।'),
('प्राचीन भारत के दार्शनिक एवं धार्मिक विचारों के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. आजीवक संप्रदाय के संस्थापक मक्खलि गोसाल थे, जो पूर्ण नियतिवाद (Niyativada) के समर्थक थे।<br>B. जैन धर्म के ''स्याद्वाद'' सिद्धांत को सप्तभंगी नय (सात स्तरीय ज्ञान) भी कहा जाता है।<br>C. बौद्ध धर्म का ''प्रतीत्यसमुत्पाद'' सिद्धांत कारण-कार्य श्रृंखला पर आधारित है।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'मक्खलि गोसाल का आजीवक दर्शन नियतिवाद पर आधारित है जिसमें कर्म का प्रभाव नहीं माना गया। स्याद्वाद जैन ज्ञानमीमांसा का मूल है और प्रतीत्यसमुत्पाद (कारण होने पर ही कार्य की उत्पत्ति) बौद्ध दर्शन का केंद्रीय आधार है।'),
('विजयनगर साम्राज्य के सामाजिक एवं प्रशासनिक ढांचे के संबंध में कौन सा कथन असत्य है?', 'विदेशी यात्रियों (दुआर्ते बारबोसा और फर्नाओ नूनीज) ने विजयनगर साम्राज्य में सती प्रथा (सहगमन) और देवदासी प्रथा के व्यापक प्रचलन का विस्तार से उल्लेख किया है।'),
('भारतीय राष्ट्रीय आंदोलन में 1905 से 1919 (उग्रवादी/राष्ट्रवादी चरण) के संदर्भ में निम्नलिखित घटनाओं का सही कालानुक्रम (Chronological Order) चुनिए:<br><br>1. कांग्रेस का सूरत विभाजन<br>2. मार्ले-मिंटो सुधार अधिनियम<br>3. दिल्ली दरबार में बंगाल विभाजन को रद्द करने की घोषणा<br>4. लखनऊ समझौता (कांग्रेस और मुस्लिम लीग संधि)', 'सूरत विभाजन: दिसंबर 1907; मार्ले-मिंटो सुधार: 1909; दिल्ली दरबार (विभाजन रद्द): दिसंबर 1911; लखनऊ समझौता: दिसंबर 1916। अतः सही क्रम 1 - 2 - 3 - 4 है।'),
('राजस्थान के भौतिक प्रदेशों एवं उनकी भू-आकृतिक विशेषताओं के संदर्भ में गलत कथन की पहचान कीजिए:', 'हाड़ौती के पठार (मध्यम काली मिट्टी क्षेत्र) में मुख्य रूप से ''वर्टीसोल्स'' (Vertisols) मृदा पाई जाती है, जबकि एरिडिसोल्स मृदा पश्चिमी शुष्क राजस्थान में पाई जाती है।'),
('विश्व भूगोल के प्रमुख औद्योगिक प्रदेशों एवं उनके उपनामों का कौन सा युग्म सुमेलित <strong>नहीं</strong> है?', 'लॉरेन (Lorraine) क्षेत्र फ्रांस में स्थित प्रसिद्ध लौह-अयस्क एवं औद्योगिक क्षेत्र है, न कि यूनाइटेड किंगडम का सूती वस्त्र क्षेत्र (UK में मैनचेस्टर/लंकाशायर प्रसिद्ध हैं)।'),
('भारत के संविधान के अनुच्छेद 356 (राष्ट्रपति शासन) के न्यायिक पुनरावलोकन के संदर्भ में सर्वोच्च न्यायालय के ऐतिहासिक ''एस.आर. बोम्मई बनाम भारत संघ (1994)'' वाद के निर्णयों में क्या शामिल नहीं था?', 'एस.आर. बोम्मई मामले में न्यायालय ने स्पष्ट किया कि यदि संसद के दोनों सदन उद्घोषणा का अनुमोदन नहीं करते हैं, या यदि अदालत उद्घोषणा को असंवैधानिक घोषित करती है, तो बर्खास्त सरकार और विधानसभा दोनों को पुनर्जीवित (Restore) किया जा सकता है।'),
('राजस्थान मानवाधिकार आयोग (SHRC) के संदर्भ में मानवाधिकार संरक्षण (संशोधन) अधिनियम, 2019 के पश्चात की स्थिति पर विचार कीजिए:<br><br>A. आयोग में एक अध्यक्ष और दो सदस्य होते हैं।<br>B. उच्च न्यायालय का कोई भी सेवानिवृत्त न्यायाधीश या मुख्य न्यायाधीश इसका अध्यक्ष बन सकता है।<br>C. अध्यक्ष एवं सदस्यों का कार्यकाल 3 वर्ष या 70 वर्ष की आयु (जो भी पहले हो) तक होता है।<br><br>उपर्युक्त में से कौन से कथन सही हैं?', '2019 संशोधन के बाद अध्यक्ष के रूप में हाईकोर्ट के रिटायर्ड चीफ जस्टिस या जज दोनों पात्र हैं। कार्यकाल 5 वर्ष से घटाकर 3 वर्ष (या 70 वर्ष की आयु) किया गया और सदस्यों की संरचना अध्यक्ष + 2 सदस्य तय की गई।'),
('राजस्थान के मुख्य सचिव (Chief Secretary) की भूमिका एवं शक्तियों के संबंध में निम्नलिखित में से कौन सा कथन सही <strong>नहीं</strong> है?', 'मुख्य सचिव का कोई निश्चित संवैधानिक या विधिक कार्यकाल नहीं होता; वह राज्य सरकार/मुख्यमंत्री के विश्वास और वरिष्ठता के आधार पर पद धारण करता है।'),
('मुद्रास्फीति (Inflation) के नियंत्रण हेतु भारतीय रिजर्व बैंक (RBI) द्वारा अपनाए जाने वाले निम्नलिखित मौद्रिक उपायों में से कौन सा ''गुणात्मक/चयनात्मक'' (Qualitative) उपकरण है?', 'CRR, SLR, बैंक दर और OMO मात्रात्मक (Quantitative) उपकरण हैं, जबकि मार्जिन आवश्यकता में बदलाव, साख की राशनिंग और नैतिक दबाव गुणात्मक/चयनात्मक (Qualitative) उपाय हैं।'),
('राजस्थान सरकार की ''मुख्यमंत्री अनुप्रति कोचिंग योजना'' के संबंध में पात्रता एवं प्रावधानों पर विचार कीजिए:<br><br>A. यह योजना विभिन्न व्यावसायिक पाठ्यक्रमों एवं प्रतियोगी परीक्षाओं की तैयारी हेतु निःशुल्क कोचिंग प्रदान करती है।<br>B. लाभार्थी परिवार की वार्षिक आय ₹8 लाख से कम होनी चाहिए या माता-पिता पे-मैट्रिक्स लेवल L-11 तक के कर्मचारी हों।<br>C. योजना में छात्राओं के लिए न्यूनतम 50% सीटों का आरक्षण अनिवार्य किया गया है।<br><br>सही विकल्प का चयन कीजिए:', 'योजना के तहत परिवार की वार्षिक आय सीमा ₹8 लाख तथा सरकारी कर्मचारियों के लिए पे-मैट्रिक्स L-11 निर्धारित है। योजना में छात्राओं के लिए 50% नहीं बल्कि कुल लाभार्थियों में 30% स्थान बालिकाओं हेतु आरक्षित रखने का प्रावधान है।'),
('जीन संपादन (Gene Editing) तकनीक ''CRISPR-Cas9'' के संबंध में निम्नलिखित कथनों में से कौन सा सही है?', 'CRISPR-Cas9 प्रणाली में Cas9 एक एंडोन्यूक्लिएज एंजाइम है जो गाइड आरएनए (gRNA) की मदद से लक्षित डीएनए खंड को सटीकता से काटकर संपादित करने में सक्षम है।'),
('ग्रीन हाइड्रोजन मिशन (National Green Hydrogen Mission) के अंतर्गत प्रयुक्त ''इलेक्ट्रोलाइजर'' तकनीक का प्राथमिक कार्य क्या है?', 'ग्रीन हाइड्रोजन उत्पादन में नवीकरणीय स्रोतों (सौर/पवन) से उत्पादित बिजली का उपयोग करके इलेक्ट्रोलाइजर द्वारा पानी के अणुओं को हाइड्रोजन ($H_2$) और ऑक्सीजन ($O_2$) में विभाजित किया जाता है।'),
('नीचे दिए गए कथन और तर्कों पर विचार कीजिए:<br><br><strong>कथन:</strong> क्या भारत में सभी स्तरों पर मतदान को अनिवार्य बना दिया जाना चाहिए?<br><strong>तर्क I:</strong> हाँ, इससे चुनावी प्रक्रिया में जनभागीदारी बढ़ेगी और लोकतंत्र अधिक मजबूत होगा।<br><strong>तर्क II:</strong> नहीं, मतदान एक लोकतांत्रिक अधिकार है, इसे दंडात्मक बाध्यता में बदलना नागरिक स्वतंत्रता के मूल सिद्धांत के विपरीत है।', 'तर्क I शासन में लोकतांत्रिक भागीदारी बढ़ाने के सकारात्मक पहलू का समर्थन करता है और तर्क II नागरिक अधिकारों एवं स्वतंत्रता के दार्शनिक आधार पर व्यावहारिक चिंता व्यक्त करता है। दोनों तर्क अपने-अपने परिप्रेक्ष्य में तार्किक और मजबूत हैं।'),
('एक सांकेतिक भाषा में यदि ''HARMONY'' को ''IBSNPOZ'' लिखा जाता है और ''RESOLVE'' को ''SFTMPWF'' लिखा जाता है, तो उसी कूट भाषा में ''DISASTER'' को क्या लिखा जाएगा?', 'प्रत्येक अक्षर में +1 का विस्थापन है: D(+1)=E, I(+1)=J, S(+1)=T, A(+1)=B, S(+1)=T, T(+1)=U, E(+1)=F, R(+1)=S -> EJTBTUFS।'),
('A, B, C, D और E एक वृत्ताकार मेज के चारों ओर केंद्र की ओर मुख करके बैठे हैं। B, E के तुरंत बाईं ओर है। C, A और D के बीच में बैठा है। A, E के तुरंत दाईं ओर है। D के तुरंत बाईं ओर कौन बैठा है?', 'केंद्रोन्मुख व्यवस्था में: E के दाईं ओर A, A के बगल में C, C के बगल में D, D के बाद B और फिर E बैठता है (क्रम दक्षिणावर्त: E - A - C - D - B)। अतः D के तुरंत बाईं ओर B स्थित है।'),
('एक व्यक्ति किसी वस्तु को उसके क्रय मूल्य से 25% अधिक पर अंकित करता है और उस पर 12% की छूट देता है। यदि वह ₹440 का शुद्ध लाभ अर्जित करता है, तो उस वस्तु का लागत मूल्य (Cost Price) क्या था?', 'माना CP = 100x; MP = 125x; SP = $125x \times 0.88 = 110x$। लाभ = $110x - 100x = 10x$। दिया है: $10x = 440 \Rightarrow x = 44$। अतः लागत मूल्य (CP) = $100 \times 44 = ₹4,000$।'),
('1 से 100 तक की प्राकृतिक संख्याओं में से यादृच्छिक रूप से चुनी गई एक संख्या के 3 या 7 का गुणज होने की प्रायिकता (Probability) क्या है?', '3 के गुणज $n(A) = \lfloor 100/3 \rfloor = 33$; 7 के गुणज $n(B) = \lfloor 100/7 \rfloor = 14$; 3 और 7 दोनों (21 के गुणज) $n(A \cap B) = \lfloor 100/21 \rfloor = 4$। कुल अनुकूल संख्याएँ = $33 + 14 - 4 = 43$।'),
('राजस्थान के एकीकरण के विभिन्न चरणों एवं उनके राज्य प्रमुख/प्रधानमंत्री के संदर्भ में निम्नलिखित युग्मों पर विचार कीजिए:<br><br>1. मत्स्य संघ : राजप्रमुख - उदयभान सिंह (धौलपुर), प्रधानमंत्री - शोभाराम कुमावत<br>2. पूर्व राजस्थान संघ : राजप्रमुख - भीमसिंह (कोटा), प्रधानमंत्री - गोकुल लाल असावा<br>3. संयुक्त राजस्थान : राजप्रमुख - भूपाल सिंह (उदयपुर), प्रधानमंत्री - माणिक्य लाल वर्मा<br>4. वृहत् राजस्थान : राजप्रमुख - सवाई मानसिंह द्वितीय (जयपुर), प्रधानमंत्री - हीरालाल शास्त्री<br><br>उपर्युक्त में से कौन से युग्म सही सुमेलित हैं?', 'राजस्थान के एकीकरण के प्रथम चरण (मत्स्य संघ - 18 मार्च 1948), द्वितीय चरण (पूर्व राजस्थान - 25 मार्च 1948), तृतीय चरण (संयुक्त राजस्थान - 18 अप्रैल 1948) और चतुर्थ चरण (वृहत् राजस्थान - 30 मार्च 1949) के सभी राजप्रमुख एवं प्रधानमंत्रियों के युग्म ऐतिहासिक रूप से पूर्णतः सही हैं।'),
('राजस्थान की हस्तकला एवं भौगोलिक संकेतक (GI Tags) के संबंध में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. कश कशीदाकारी शिल्प और उस्ता कला शिल्प बीकानेर जिले से संबंधित हैं जिन्हें जीआई टैग प्राप्त है।<br>B. कोफ्तगारी धातु शिल्प का संबंध उदयपुर से तथा बंधेज शिल्प का संबंध जोधपुर से है।<br>C. नाथद्वारा की पिछवाई पेंटिंग और जाजम छपाई (चित्तौड़गढ़) दोनों को संयुक्त रूप से वर्ष 2023-24 में जीआई टैग प्रदान किया गया।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'बीकानेर की उस्ता कला एवं कशीदाकारी क्राफ्ट, उदयपुर का कोफ्तगारी मेटल क्राफ्ट, जोधपुर का बंधेज क्राफ्ट और नाथद्वारा की पिछवाई कला को GI टैग दिया गया है। जाजम/दाबू प्रिंट चित्तौड़गढ़ से है परंतु इसे नाथद्वारा पिछवाई के साथ संयुक्त रूप से हाल में जारी 5 विशिष्ट शिल्पों की सूची में शामिल नहीं किया गया था।'),
('मध्यकालीन भारत के सूफी और भक्ति संतों के सिद्धांतों के संदर्भ में निम्नलिखित में से कौन सा कथन <strong>असत्य</strong> है?', 'शेख अहमद सरहिंदी नक्शबंदी सिलसिले के कट्टर रूढ़िवादी संत थे। उन्होंने इब्न अल-अरबी के सर्वेश्वरवादी सिद्धांत ''वहदत-उल-वुजूद'' (अस्तित्व की एकता) का कड़ा विरोध किया और इसके स्थान पर ''वहदत-उश-शुहूद'' (प्रत्यक्ष की एकता) का प्रतिपादन किया।'),
('मुगलकालीन मनसबदारी व्यवस्था के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>1. ''जात'' पद से मनसबदार के व्यक्तिगत वेतन और प्रशासनिक पदानुक्रम में उसकी स्थिति का निर्धारण होता था।<br>2. ''सवार'' पद से यह निर्धारित होता था कि मनसबदार को कितने घुड़सवार और सैन्य दल का रखरखाव करना है।<br>3. जहांगीर ने मनसबदारी में ''दुआस्पा-सिंहअस्पा'' प्रथा प्रारंभ की, जिसके तहत बिना जात पद बढ़ाए अतिरिक्त सवार रखे जा सकते थे।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'अकबर द्वारा शुरू की गई मनसबदारी व्यवस्था में ''जात'' पद प्रतिष्ठा/वेतन तय करता था और ''सवार'' सैन्य दायित्व। जहांगीर ने इसमें ''दुआस्पा-सिंहअस्पा'' नियम जोड़ा ताकि राज्य पर वित्तीय भार (जात पद) बढ़ाए बिना चुनिंदा सैन्य दलों की संख्या दुगुनी की जा सके।'),
('19वीं सदी के प्रमुख किसान एवं जनजातीय आंदोलनों के संदर्भ में सही कूट का चयन कीजिए:<br><br><table style=''width:100%; border-collapse: collapse; margin-top:5px;'' border=''1''><tr><th>आंदोलन</th><th>प्रमुख नेतृत्वकर्ता</th></tr><tr><td>A. संथाल विद्रोह (1855-56)</td><td>i. सिद्धो और कान्हू मुर्मू</td></tr><tr><td>B. मुंडा उलगुलान (1899-1900)</td><td>ii. बिरसा मुंडा</td></tr><tr><td>C. रम्पा विद्रोह (1879)</td><td>iii. अल्लूरी सीताराम राजू (परवर्ती) / तम्मा दोरा</td></tr><tr><td>D. भगत आंदोलन (राजस्थान)</td><td>iv. गोविंद गिरि</td></tr></table>', 'संथाल विद्रोह का नेतृत्व सिद्धो-कान्हू ने किया; मुंडा विद्रोह बिरसा मुंडा के अधीन हुआ; रम्पा क्षेत्र में तम्मा दोरा एवं बाद में 1922 में अल्लूरी सीताराम राजू प्रसिद्ध हुए; और राजस्थान के दक्षिणी वागड़ क्षेत्र में भीलों के उत्थान हेतु भगत आंदोलन गुरु गोविंद गिरि द्वारा चलाया गया।'),
('राजस्थान के अपवाह तंत्र के संदर्भ में निम्नलिखित नदियों एवं उनके त्रिवेणी संगमों का कौन सा युग्म सुमेलित <strong>नहीं</strong> है?', 'बेणेश्वर (डूंगरपुर) वास्तव में सोम, माही और जाखम नदियों के त्रिवेणी संगम पर स्थित है, न कि गोदावरी-कावेरी-ताप्ती पर (ये नदियाँ राजस्थान में बहती भी नहीं हैं)। शेष तीनों युग्म — बीगोद, राजमहल और रामेश्वर घाट — पूर्णतः सही सुमेलित हैं।'),
('भारत के जलवायु वर्गीकरण (कोपेन के अनुसार) के संदर्भ में राजस्थान के क्षेत्रों का सही सुमेलन चुनिए:<br><br>1. BWhw : जैसलमेर, पश्चिमी बीकानेर, फलौदी (अत्यंत शुष्क मरुस्थलीय)<br>2. BShw : जालौर, पाली, नागौर, सीकर, झुंझुनूं (अर्धशुष्क/स्टेपी)<br>3. Cwg : अरावली के पूर्वी एवं दक्षिणी-पूर्वी मैदानी भाग<br>4. Aw : डूंगरपुर, बांसवाड़ा, झालावाड़ एवं माउंट आबू (उष्णकटिबंधीय आर्द्र)<br><br>उपर्युक्त में से कौन से सही हैं?', 'कोपेन के जलवायु वर्गीकरण के अनुसार राजस्थान के चार प्रमुख भाग हैं: BWhw (शुष्क मरुस्थलीय), BShw (अर्ध-शुष्क स्टेपी), Cwg (गंगा-तुल्य पूर्वी मैदान) तथा Aw (दक्षिणी एवं दक्षिण-पूर्वी आर्द्र क्षेत्र)। चारों सुमेलित हैं।'),
('विश्व के प्रमुख महासागरीय जलधाराओं के संदर्भ में निम्नलिखित में से कौन सी एक ''शीत जलधारा'' (Cold Current) <strong>नहीं</strong> है?', 'क्यूरोशियो धारा उत्तरी प्रशांत महासागर की एक ''गर्म'' महासागरीय जलधारा है जो फिलीपींस तट से जापान की ओर बहती है। बेंगुएला, हम्बोल्ट और लेब्राडोर सभी ठंडी जलधाराएं हैं।'),
('भारतीय संविधान के ''मूल अधिकारों'' एवं ''राज्य के नीति निदेशक तत्वों'' (DPSP) के मध्य टकराव के संदर्भ में न्यायिक निर्णयों का सही कालानुक्रम क्या है?<br><br>1. चंपकम दोराइराजन वाद<br>2. गोलकनाथ वाद<br>3. केशवानंद भारती वाद<br>4. मिनर्वा मिल्स वाद', 'चंपकम दोराइराजन (1951), गोलकनाथ वाद (1967), केशवानंद भारती वाद (1973), और मिनर्वा मिल्स वाद (1980)। मिनर्वा मिल्स वाद में सर्वोच्च न्यायालय ने कहा कि भारतीय संविधान मूल अधिकारों और नीति निदेशक तत्वों के मध्य संतुलन की नींव पर टिका है।'),
('भारतीय संविधान के अनुच्छेद 280 के तहत गठित ''सोलहवें वित्त आयोग'' (16th Finance Commission) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. नीति आयोग के पूर्व उपाध्यक्ष डॉ. अरविंद पनगढ़िया को इसका अध्यक्ष नियुक्त किया गया है।<br>B. यह आयोग 1 अप्रैल 2026 से शुरू होने वाली 5 वर्षों की अवधि के लिए अपनी संस्तुतियां देगा।<br>C. आयोग के संदर्भ शर्तों (ToR) में आपदा प्रबंधन निधि के वित्तपोषण की वर्तमान व्यवस्था की समीक्षा करना भी शामिल है।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', '16वें वित्त आयोग का गठन दिसंबर 2023 में किया गया जिसके अध्यक्ष डॉ. अरविंद पनगढ़िया हैं। इसकी संस्तुतियां 2026-2031 की अवधि हेतु होंगी और इसके कार्यक्षेत्र में कर विभाजन, सहायता अनुदान और आपदा प्रबंधन उपकर/निधि की समीक्षा सम्मिलित है।'),
('राजस्थान लोकायुक्त एवं उप-लोकायुक्त अधिनियम, 1973 के क्षेत्राधिकार के संबंध में निम्नलिखित में से कौन लोकायुक्त की जांच के दायरे में <strong>नहीं</strong> आता है?', 'राजस्थान लोकायुक्त के जांच दायरे से मुख्यमंत्री, उच्च न्यायालय के न्यायाधीश, राजस्थान लोक सेवा आयोग (RPSC) के अध्यक्ष/सदस्य, विधानसभा सचिवालय के कर्मचारी तथा राज्य के ''विधायक (MLAs)'' बाहर रखे गए हैं।'),
('भारत में भुगतान संतुलन (Balance of Payments - BoP) के ''चालू खाते'' (Current Account) में निम्नलिखित में से किसे शामिल <strong>नहीं</strong> किया जाता है?', 'FDI और FPI पूंजीगत खाते (Capital Account) के घटक हैं, जबकि दृश्य व्यापार (वस्तुएं), अदृश्य व्यापार (सेवाएं) और एकपक्षीय अंतरण (Remittances) चालू खाते (Current Account) के भाग होते हैं।'),
('राजस्थान की ''इंदिरा गांधी शहरी रोजगार गारंटी योजना'' (IRGY-Urban) के संदर्भ में सत्य कथन की पहचान कीजिए:', 'यह राजस्थान राज्य सरकार द्वारा 100% वित्तपोषित योजना है जो शहरी स्थानीय निकायों के 18-60 वर्ष के जन आधार कार्ड धारक परिवारों को प्रतिवर्ष 125 दिवस का अकुशल रोजगार उपलब्ध कराती है।'),
('जैव प्रौद्योगिकी में ''रिकॉम्बिनेंट डीएनए तकनीक'' (rDNA Technology) के चरणों का सही वैज्ञानिक क्रम क्या है?<br><br>1. रिस्ट्रिक्शन एंडोन्यूक्लिएज द्वारा डीएनए को विशिष्ट स्थलों पर काटना<br>2. आनुवंशिक पदार्थ (डीएनए) का पृथक्करण<br>3. डीएनए लिगेज की सहायता से डीएनए खंड को वाहक (Vector) में जोड़ना<br>4. पुनः संयोजक डीएनए को परपोषी कोशिका में स्थानांतरित करना', 'rDNA तकनीक का सही क्रम: सर्वप्रथम कोशिका से DNA का पृथक्करण (2) -> रिस्ट्रिक्शन एंजाइम से काटना (1) -> लाइगेज द्वारा वेक्टर में जोड़ना (3) -> परपोषी (Host) में स्थानांतरण (4)।'),
('मानव पोषण एवं स्वास्थ्य के संदर्भ में विभिन्न विटामिनों एवं उनकी कमी से होने वाले रोगों का कौन सा युग्म सही सुमेलित <strong>नहीं</strong> है?', 'जीरोफ्थैल्मिया (Xerophthalmia) और रतौंधी विटामिन A (रेटिनॉल) की कमी से होते हैं। विटामिन D की कमी से बच्चों में रिकेट्स (Rickets) तथा वयस्कों में ऑस्टियोमलेशिया होता है।'),
('पारिस्थितिकी तंत्र में ''ऊर्जा के पिरामिड'' (Pyramid of Energy) के संदर्भ में सार्वभौमिक सत्य कथन कौन सा है?', 'ऊष्मागतिकी के द्वितीय नियम और लिंडमैन के 10% ऊर्जा नियम के अनुसार पोषण स्तरों में ऊपर जाने पर ऊर्जा सदैव घटती है। अतः ऊर्जा का पिरामिड बिना किसी अपवाद के सदैव सीधा (Upright) होता है।'),
('नीचे दिए गए प्रश्न में एक कथन के उपरांत दो कार्यवाहियां (I) एवं (II) दी गई हैं:<br><br><strong>कथन:</strong> भारी मानसून वर्षा के कारण राज्य के पश्चिमी जिलों के कई प्रमुख शहरों में जलभराव और बाढ़ जैसी स्थिति उत्पन्न हो गई है।<br><br><strong>कार्यवाही I:</strong> राज्य आपदा मोचन बल (SDRF) और राहत दलों को तत्काल प्रभावित क्षेत्रों में नावों और राशन सामग्री के साथ तैनात किया जाना चाहिए।<br><strong>कार्यवाही II:</strong> निचले इलाकों में रहने वाले सभी नागरिकों को तुरंत सुरक्षित एवं ऊंचे स्थानों पर बने राहत शिविरों में स्थानांतरित किया जाना चाहिए।', 'आपदा प्रबंधन प्रोटोकॉल के अनुसार आपात राहत दलों की तत्काल तैनाती और खतरे वाले क्षेत्रों से लोगों की सुरक्षित निकासी दोनों तात्कालिक, प्रशासनिक रूप से अनिवार्य और व्यावहारिक कदम हैं।'),
('एक सांकेतिक भाषा में ''617'' का अर्थ ''sweet and hot'', ''735'' का अर्थ ''coffee is sweet'' और ''263'' का अर्थ ''tea is hot'' है। उस कोड भाषा में ''coffee'' के लिए कौन सा अंक प्रयुक्त हुआ है?', '''sweet'' पहले और दूसरे में कॉमन है = 7। ''is'' दूसरे और तीसरे में कॉमन है = 3। दूसरे वाक्य में ''coffee'' शेष बचा और अंक ''5'' बचा। अतः coffee = 5।'),
('एक व्यक्ति ₹12,000 की राशि 10% प्रति वर्ष चक्रवृद्धि ब्याज की दर से 1.5 वर्ष के लिए उधार लेता है, जहाँ ब्याज अर्धवार्षिक (Half-yearly) संयोजित होता है। परिपक्वता पर देय कुल चक्रवृद्धि ब्याज कितना होगा?', 'अर्धवार्षिक दर $R = 5\%$, समय $n = 3$ अर्धवर्ष। $A = 12000 \times (1 + 5/100)^3 = 12000 \times (21/20)^3 = 12000 \times \frac{9261}{8000} = 1.5 \times 9261 = ₹13,891.50$। चक्रवृद्धि ब्याज = $13,891.50 - 12000 = ₹1,891.50$।'),
('8 व्यक्तियों के एक समूह का औसत भार 2.5 किग्रा बढ़ जाता है जब 56 किग्रा भार वाले एक व्यक्ति के स्थान पर एक नया व्यक्ति समूह में शामिल होता है। नए व्यक्ति का भार कितना है?', 'कुल भार में कुल वृद्धि = $8 \times 2.5 = 20$ किग्रा। नए व्यक्ति का भार = पुराने व्यक्ति का भार + कुल वृद्धि = $56 + 20 = 76$ किग्रा।'),
('राजस्थान के प्रमुख संत एवं उनके संप्रदायों के संदर्भ में निम्नलिखित युग्मों पर विचार कीजिए:<br><br>1. जसनाथी संप्रदाय : कतरियासर (बीकानेर) — 36 नियमों का पालन एवं अग्नि नृत्य<br>2. विश्नोई संप्रदाय : समराथल धोरा/मुकाम — 29 नियमों का पालन एवं ''पाहल'' संस्कार<br>3. चरणदासी संप्रदाय : डेहरा (अलवर)/दिल्ली — 42 नियमों का पालन एवं सगुण-निर्गुण समन्वय<br>4. निरंजनी संप्रदाय : गाढ़ा (डीडवाना) — संत हरिदास जी द्वारा प्रवर्तित<br><br>उपर्युक्त में से कौन से युग्म सही सुमेलित हैं?', 'जसनाथी संप्रदाय (36 नियम, कतरियासर, अग्नि नृत्य), विश्नोई संप्रदाय (29 नियम, जाम्भोजी), चरणदासी संप्रदाय (42 नियम, चरणदास जी, भारत पर नादिरशाह के आक्रमण की भविष्यवाणी), और निरंजनी संप्रदाय (हरिदास जी - कलिकाल के वाल्मीकि) चारों सुमेलित हैं।'),
('राजस्थान की चित्रकला शैलियों एवं उनके प्रमुख भित्तिचित्र/विशेषताओं के संदर्भ में गलत कथन का चयन कीजिए:', 'बीकानेर शैली पर मुग़ल शैली का गहरा प्रभाव था (उस्ता कला व मथेरण कला के कलाकार मुग़ल दरबार से आए थे)। अतः यह कथन गलत है कि बीकानेर शैली में मुग़ल प्रभाव अनुपस्थित था।'),
('मौर्योत्तर कालीन कुषाण शासक ''कनिष्क प्रथम'' के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. उसने 78 ई. में ''शक संवत'' प्रारंभ किया, जो वर्तमान में भारत का राष्ट्रीय पंचांग है।<br>B. उसके शासनकाल में कश्मीर के कुंडलवन में चतुर्थ बौद्ध संगीति आयोजित की गई थी जिसकी अध्यक्षता वसुमित्र ने की।<br>C. उसके दरबार में चरक, अश्वघोष, नागार्जुन और पार्श्व जैसे विद्वान संरक्षण प्राप्त थे।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'कनिष्क प्रथम ने 78 ई. में शक संवत की शुरुआत की। चतुर्थ बौद्ध संगीति कुंडलवन (कश्मीर) में वसुमित्र की अध्यक्षता और अश्वघोष के उपाध्यक्ष पद पर हुई। चरक (चरक संहिता) एवं नागार्जुन (माध्यमिक सूत्र) कनिष्क के राजदरबार में थे।'),
('1857 के स्वतंत्रता संग्राम के दौरान राजस्थान की विभिन्न छावनियों में हुए विद्रोह के संदर्भ में निम्नलिखित में से कौन सा युग्म सुमेलित <strong>नहीं</strong> है?', 'ब्यावर और खेरवाड़ा छावनियों ने 1857 की क्रांति में भाग नहीं लिया था। मेजर बर्टन की हत्या और सुनियोजित जन-विद्रोह 15 अक्टूबर 1857 को ''कोटा'' रियासत में जयदयाल और मेहराब खान के नेतृत्व में हुआ था।'),
('भारत में प्रायद्वीपीय पठार की भू-आकृतिक विशेषताओं के संदर्भ में कौन सा कथन सही है?', 'अनाईमुडी (अनामलाई पहाड़ियों पर स्थित, 2695 मीटर) दक्षिण भारत की सबसे ऊंची चोटी है। पश्चिमी घाट पूर्वी घाट की तुलना में ऊंचे और निरंतर हैं। नर्मदा और ताप्ती नदियां भ्रंश घाटी से होकर अरब सागर में गिरती हैं और ज्वारनदमुख (Estuary) बनाती हैं।'),
('राजस्थान में खनिज संसाधनों के वितरण के संदर्भ में निम्नलिखित में से कौन सा समूह ''सीसा-जस्ता'' (Lead-Zinc) उत्पादक क्षेत्रों को सही प्रदर्शित करता है?', 'जावर, राजपुरा-दरीबा, रामपुरा-आगूचा (देश का सबसे समृद्ध अयस्क भंडार) और चौथ का बरवाड़ा सीसा-जस्ता उत्पादक क्षेत्र हैं। खेतड़ी/खो-दरीबा तांबा, डेगाना टंगस्टन और झामर-कोटड़ा रॉक फॉस्फेट के प्रमुख क्षेत्र हैं।'),
('भारत के मुख्य निर्वाचन आयुक्त (CEC) एवं निर्वाचन आयुक्तों (EC) की नियुक्ति के संबंध में संसद द्वारा पारित नवीनतम अधिनियम के अनुसार चयन समिति (Selection Committee) में कौन शामिल होते हैं?', 'मुख्य निर्वाचन आयुक्त और अन्य निर्वाचन आयुक्त (नियुक्ति, सेवा की शर्तें और पदावधि) अधिनियम के अनुसार चयन समिति में: (1) प्रधानमंत्री (अध्यक्ष), (2) लोकसभा में विपक्ष के नेता/एकल सबसे बड़े दल के नेता, और (3) प्रधानमंत्री द्वारा नामित एक केंद्रीय कैबिनेट मंत्री शामिल होते हैं।'),
('संविधान के अनुच्छेद 368 के अंतर्गत संविधान संशोधन की प्रक्रिया के संदर्भ में निम्नलिखित में से कौन सा कथन <strong>असत्य</strong> है?', 'अनुच्छेद 368 के तहत संविधान संशोधन विधेयक के लिए दोनों सदनों में विशेष बहुमत से अलग-अलग पारित होना अनिवार्य है; इसमें गतिरोध दूर करने हेतु अनुच्छेद 108 के तहत संयुक्त बैठक (Joint Sitting) का कोई प्रावधान नहीं है।'),
('राजस्थान में ''ग्राम सभा'' (Gram Sabha) के संदर्भ में राजस्थान पंचायती राज अधिनियम, 1994 के प्रावधानों के अनुसार कौन सा कथन सही है?', 'ग्राम सभा पंचायती राज की प्राथमिक और बुनियादी संस्था है, जिसमें ग्राम पंचायत क्षेत्र की मतदाता सूची में पंजीकृत सभी नागरिक सदस्य होते हैं। इसकी अध्यक्षता सरपंच (या उसकी अनुपस्थिति में उप-सरपंच) करता है।'),
('अर्थशास्त्र में ''गिफेन वस्तुएं'' (Giffen Goods) और ''वेबलेन वस्तुएं'' (Veblen Goods) के संदर्भ में मांग के नियम (Law of Demand) का क्या प्रभाव पड़ता है?', 'गिफेन वस्तुएं (अति निकृष्ट वस्तुएं, जहाँ नकारात्मक आय प्रभाव प्रतिस्थापन प्रभाव से अधिक होता है) और वेबलेन वस्तुएं (प्रतिष्ठासूचक विलासिता वस्तुएं) दोनों ही मांग के नियम के अपवाद हैं, जिनमें कीमत बढ़ने पर मांग बढ़ सकती है।'),
('राजस्थान सरकार के ''मुख्यमंत्री आयुष्मान आरोग्य योजना'' (पूर्ववर्ती चिरंजीवी योजना) के संदर्भ में मुख्य विशेषताओं पर विचार कीजिए:<br><br>A. यह योजना पात्र परिवारों को कैशलेस अंतःरोगी (IPD) उपचार सुविधा प्रदान करती है।<br>B. राष्ट्रीय खाद्य सुरक्षा अधिनियम (NFSA) एवं सामाजिक-आर्थिक जनगणना (SECC) के पात्र परिवारों का प्रीमियम राज्य सरकार वहन करती है।<br>C. अन्य गैर-पात्र परिवार प्रतिवर्ष एक निश्चित प्रीमियम का भुगतान करके इस योजना से जुड़ सकते हैं।<br><br>सही कूट चुनिए:', 'मुख्यमंत्री आयुष्मान आरोग्य योजना (MAAY) के तहत चिन्हित श्रेणियों (NFSA, लघु/सीमांत कृषक, संविदाकर्मी आदि) का संपूर्ण प्रीमियम राज्य सरकार देती है, जबकि शेष परिवार निर्धारित वार्षिक प्रीमियम (जैसे ₹850) देकर कैशलेस स्वास्थ्य सुरक्षा प्राप्त कर सकते हैं।'),
('प्रकाशिकी (Optics) में ''पूर्ण आंतरिक परावर्तन'' (Total Internal Reflection - TIR) की घटना घटित होने के लिए अनिवार्य शर्तें क्या हैं?<br><br>1. प्रकाश की किरण को सघन माध्यम (Denser Medium) से विरल माध्यम (Rare Medium) में जाना चाहिए।<br>2. आपतन कोण (Angle of Incidence) का मान दोनों माध्यमों के क्रांतिक कोण (Critical Angle) से अधिक होना चाहिए।<br>3. प्रकाश का प्रकीर्णन तरंगदैर्घ्य के चतुर्थ घात के व्युत्क्रमानुपाती होना चाहिए।<br><br>सही विकल्प का चयन कीजिए:', 'TIR हेतु दो आवश्यक शर्तें हैं: (1) प्रकाश सघन से विरल माध्यम में प्रवेश करे, और (2) आपतन कोण > क्रांतिक कोण ($i > C$)। ऑप्टिकल फाइबर और मरीचिका इसी सिद्धांत पर कार्य करते हैं। कथन 3 रैले के प्रकीर्णन नियम से संबंधित है।'),
('परमाणु संरचना एवं रेडियोधर्मिता (Radioactivity) के संदर्भ में निम्नलिखित कणों की भेदन क्षमता (Penetrating Power) का सही बढ़ता क्रम (Ascending Order) कौन सा है?', 'अल्फा ($\alpha$) कणों का द्रव्यमान अधिक होने के कारण भेदन क्षमता सबसे कम होती है; बीटा ($\beta$) कणों की मध्यम तथा द्रव्यमानहीन उच्च ऊर्जा वाली गामा ($\gamma$) किरणों की भेदन क्षमता सर्वाधिक होती है।'),
('मानव शरीर में रक्त परिसंचरण एवं रक्त समूहों (ABO Blood Groups) के संदर्भ में सत्य कथन चुनिए:', 'रक्त समूह AB के RBCs पर A और B दोनों एंटीजन होते हैं परंतु प्लाज्मा में कोई एंटीबॉडी नहीं होती, इसलिए यह किसी भी समूह से रक्त ले सकता है (Universal Recipient)। रक्त समूह O में कोई एंटीजन नहीं होता।'),
('मॉन्ट्रियल प्रोटोकॉल (Montreal Protocol) और किगाली संशोधन (Kigali Amendment) का प्राथमिक उद्देश्य क्या है?', '1987 का मॉन्ट्रियल प्रोटोकॉल ओजोन-क्षयकारी पदार्थों (CFCs/Halons) के नियंत्रण हेतु था, और 2016 के किगाली संशोधन द्वारा उच्च ग्लोबल वार्मिंग क्षमता वाले HFCs को चरणबद्ध रूप से कम करने का वैश्विक लक्ष्य जोड़ा गया।'),
('नीचे दिए गए प्रश्न में तीन कथनों के आधार पर कौन सा निष्कर्ष तार्किक रूप से निकलता है?<br><br><strong>कथन:</strong><br>1. सभी वैज्ञानिक शोधकर्ता हैं।<br>2. कुछ शोधकर्ता शिक्षक हैं।<br>3. कोई शिक्षक प्रशासक नहीं है।<br><br><strong>निष्कर्ष:</strong><br>I. कुछ शोधकर्ता प्रशासक नहीं हैं।<br>II. कुछ वैज्ञानिक शिक्षक हैं।', 'जो शोधकर्ता ''शिक्षक'' हैं, वे कभी ''प्रशासक'' नहीं हो सकते (क्योंकि कोई शिक्षक प्रशासक नहीं है)। अतः वे शोधकर्ता निश्चित रूप से प्रशासक नहीं होंगे (निष्कर्ष I सत्य है)। वैज्ञानिकों और शिक्षकों के बीच सीधा संबंध कथन में नहीं दिया गया है।'),
('दी गई संख्या श्रेणी में प्रश्नवाचक चिन्ह (?) के स्थान पर कौन सी संख्या आएगी?<br><br>6, 13, 28, 59, 122, ?', 'पैटर्न: $6 \times 2 + 1 = 13$, $13 \times 2 + 2 = 28$, $28 \times 2 + 3 = 59$, $59 \times 2 + 4 = 122$, $122 \times 2 + 5 = 249$।'),
('एक घड़ी में जब समय 4 बजकर 40 मिनट हो रहा हो, तो घंटे की सुई और मिनट की सुई के बीच का आंतरिक कोण (Angle) कितने डिग्री होगा?', 'सूत्र: $\theta = |30H - \frac{11}{2}M|$। यहाँ $H=4, M=40$। $\theta = |30(4) - \frac{11}{2}(40)| = |120 - 220| = |-100| = 100°$।'),
('दो पाइप A और B एक टंकी को क्रमशः 20 मिनट और 30 मिनट में भर सकते हैं, जबकि तीसरा पाइप C पूरी भरी टंकी को 15 मिनट में खाली कर सकता है। यदि तीनों पाइपों को एक साथ खोल दिया जाए, तो खाली टंकी को भरने में कितना समय लगेगा?', '1 मिनट का कुल कार्य = $\frac{1}{20} + \frac{1}{30} - \frac{1}{15} = \frac{3 + 2 - 4}{60} = \frac{1}{60}$ भाग प्रति मिनट। अतः पूरी टंकी भरने में $60$ मिनट का समय लगेगा।'),
('52 ताश के पत्तों की एक अच्छी तरह फेंटी गई गड्डी में से एक पत्ता निकाला जाता है। निकाले गए पत्ते के ''हुकुम का पत्ता'' (Spade) या एक ''इक्का'' (Ace) होने की प्रायिकता क्या है?', 'हुकुम के कुल पत्ते $n(A) = 13$, कुल इक्के $n(B) = 4$, हुकुम का इक्का (उभयनिष्ठ) $n(A \cap B) = 1$। $n(A \cup B) = 13 + 4 - 1 = 16$। प्रायिकता $P = \frac{16}{52} = \frac{4}{13}$।'),
('राजस्थान में ''मिशन निर्यातक बनो'' (Mission Niryatak Bano) और राज्य की निर्यात प्रोत्साहन नीतियों के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. यह मिशन उद्योग एवं वाणिज्य विभाग तथा राजस्थान लघु उद्योग निगम (RAJSICO) द्वारा संयुक्त रूप से प्रारंभ किया गया।<br>B. राज्य से होने वाले कुल निर्यातों में इंजीनियरिंग वस्तुएं, रत्न एवं आभूषण, कपड़ा, हस्तशिल्प और कृषि-खाद्य उत्पाद शीर्ष 5 मदों में शामिल हैं।<br>C. राजस्थान एक्सपोर्ट प्रमोशन काउंसिल (REPC) को कंपनी अधिनियम के तहत एक गैर-लाभकारी स्वायत्त संस्था के रूप में गठित किया गया है।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'मिशन निर्यातक बनो राज्य में स्थानीय उद्यमियों को IEC कोड जारी करवाकर निर्यात बढ़ाने हेतु उद्योग विभाग और रीको/राजसिको द्वारा संचालित है। राजस्थान से शीर्ष 5 निर्यात उत्पाद (इंजीनियरिंग, टेक्सटाइल्स, जेम्स & ज्वैलरी, हैंडीक्राफ्ट्स, केमिकल) लगभग 60% से अधिक निर्यात का हिस्सा हैं तथा REPC राज्य का शीर्ष निर्यात निकाय है।'),
('राजस्थान के प्रमुख जलदुर्गों एवं उनके स्थापत्य के संदर्भ में निम्नलिखित युग्मों पर विचार कीजिए:<br><br>1. गागरोन दुर्ग (झालावाड़) : आहु और कालीसिंध नदियों के संगम पर स्थित (बिना किसी नींव के चट्टान पर निर्मित)<br>2. भैंसरोड़गढ़ दुर्ग (चित्तौड़गढ़) : चंबल और बामनी नदियों के संगम पर स्थित (राजस्थान का वेल्लोर)<br>3. शेरगढ़ दुर्ग (बारां) : परवन नदी के तट पर स्थित (कोशवर्धन दुर्ग)<br>4. मनोहर थाना दुर्ग (झालावाड़) : परवन और कालीखाड़ नदियों के संगम पर स्थित<br><br>उपर्युक्त में से कौन से युग्म सही सुमेलित हैं?', 'गागरोन (आहू-कालीसिंध संगम), भैंसरोड़गढ़ (चंबल-बामनी संगम), शेरगढ़/कोशवर्धन (परवन तट) और मनोहर थाना (परवन-कालीखाड़ संगम) राजस्थान के प्रमुख जलदुर्ग (औदक दुर्ग) हैं। चारों युग्म पूर्णतः सही हैं।'),
('अशोक के प्रमुख शिलालेखों एवं उनकी अवस्थिति के संदर्भ में निम्नलिखित में से कौन सा युग्म सुमेलित <strong>नहीं</strong> है?', 'एरागुड़ी शिलालेख आंध्र प्रदेश के कुरनूल जिले में स्थित है (न कि कर्नाटक में)। यहाँ ब्राह्मी लिपि को बूस्ट्रोफीडन (Boustrophedon - एक पंक्ति दाएं से बाएं, अगली पंक्ति बाएं से दाएं) शैली में उत्कीर्ण किया गया है।'),
('भारतीय राष्ट्रीय कांग्रेस के ''कराची अधिवेशन (1931)'' के संबंध में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. इस अधिवेशन की अध्यक्षता सरदार वल्लभभाई पटेल ने की थी।<br>B. अधिवेशन में गांधी-इरविन समझौते का अनुमोदन किया गया।<br>C. कांग्रेस ने पहली बार ''मौलिक अधिकारों'' और ''राष्ट्रीय आर्थिक कार्यक्रमों'' पर प्रस्ताव पारित किया जिसका मसौदा पं. जवाहरलाल नेहरू ने तैयार किया था।<br><br>सही कूट का चयन कीजिए:', 'मार्च 1931 के कराची अधिवेशन में सरदार पटेल की अध्यक्षता में गांधी-इरविन समझौते को मंजूरी दी गई तथा पं. जवाहरलाल नेहरू द्वारा तैयार मूल अधिकारों एवं राष्ट्रीय आर्थिक नीति का ऐतिहासिक प्रस्ताव पारित किया गया।'),
('भारत के प्रमुख बायोस्फीयर रिजर्व (Biosphere Reserves) और उनके राज्यों का कौन सा युग्म सही सुमेलित <strong>नहीं</strong> है?', 'अगस्त्यमलाई बायोस्फीयर रिजर्व का विस्तार पश्चिमी घाट के दक्षिणी छोर पर केरल और तमिलनाडु दोनों राज्यों में फैला हुआ है, यह केवल तमिलनाडु तक सीमित नहीं है।'),
('राजस्थान में ''पेट्रोलिफेरस बेसिन'' (Petroliferous Basins) के वर्गीकरण के संदर्भ में कौन सा कथन असत्य है?', 'बीकानेर-नागौर बेसिन (पूनम क्षेत्र) में भारी कच्चे तेल के साथ-साथ खनिज तेल व सह-उत्पादित हाइड्रोकार्बन भंडार प्राप्त हुए हैं। राजस्थान के 4 बेसिन: बाड़मेर-सांचौर, जैसलमेर, बीकानेर-नागौर और विंध्यन बेसिन हैं।'),
('भारतीय संविधान में ''संसदीय विशेषाधिकार'' (Parliamentary Privileges - अनुच्छेद 105 एवं 194) के संदर्भ में असत्य कथन चुनिए:', 'संसदीय विशेषाधिकार के अंतर्गत गिरफ्तारी से उन्मुक्ति केवल ''दीवानी मामलों'' में उपलब्ध है। यह आपराधिक मामलों, देशद्रोह या निवारक निरोध (Preventive Detention) के मामलों में लागू नहीं होती है।'),
('भारतीय प्रतिस्पर्धा आयोग (CCI) के गठन, शक्तियों और अधिदेश के संबंध में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. यह प्रतिस्पर्धा अधिनियम, 2002 के तहत स्थापित एक सांविधिक (Statutory) एवं अर्द्ध-न्यायिक निकाय है।<br>B. इसका मुख्य उद्देश्य बाजार में प्रतिस्पर्धा-रोधी करारों (Anti-competitive agreements) और प्रमुख स्थिति के दुरुपयोग (Abuse of dominant position) को रोकना है।<br>C. डिजिटल बाजारों में निष्पक्ष प्रतिस्पर्धा और एल्गोरिद्मिक मूल्य निर्धारण पर निगरानी हेतु इसने ''डिजिटल मार्केट डेटा यूनिट'' की स्थापना की है।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'CCI एक सांविधिक निकाय है जो प्रतिस्पर्धा अधिनियम, 2002 को लागू करता है। यह अनुचित व्यापार व्यवहारों, बड़े विलय-अधिग्रहणों तथा डिजिटल प्लेटफॉर्मों के प्रतिस्पर्धा-रोधी व्यवहारों की जांच व नियमन करता है।'),
('राजस्थान में ''राज्य उपभोक्ता विवाद प्रतितोष आयोग'' (State Consumer Disputes Redressal Commission) के संदर्भ में उपभोक्ता संरक्षण अधिनियम, 2019 के अनुसार आर्थिक क्षेत्राधिकार (Pecuniary Jurisdiction) क्या है?', 'उपभोक्ता संरक्षण अधिनियम 2019 (और 2021 के संशोधित नियमों) के तहत: जिला उपभोक्ता आयोग ₹50 लाख/₹1 करोड़ तक, राज्य आयोग ₹1 करोड़ से ₹10 करोड़ तक के दावों की सुनवाई करता है, तथा ₹10 करोड़ से ऊपर के मामले राष्ट्रीय उपभोक्ता आयोग (NCDRC) के क्षेत्राधिकार में आते हैं।'),
('अर्थव्यवस्था में ''तरलता जाल'' (Liquidity Trap) की स्थिति के संदर्भ में निम्नलिखित में से कौन सा प्रभाव देखा जाता है?', 'कीन्स के अनुसार, ''तरलता जाल'' वह आर्थिक स्थिति है जहाँ नाममात्र ब्याज दरें शून्य या न्यूनतम स्तर के करीब आ जाती हैं। ऐसी स्थिति में लोग बॉन्ड या प्रतिभूतियों में निवेश करने के बजाय नकदी अपने पास रखना पसंद करते हैं, जिससे परंपरागत मौद्रिक नीति निष्प्रभावी हो जाती है।'),
('राजस्थान सरकार की ''मुख्यमंत्री लघु उद्योग प्रोत्साहन योजना'' (MLUPY) के तहत विनिर्माण, सेवा एवं व्यापार क्षेत्र के उद्यमों हेतु ऋण एवं ब्याज अनुदान के संबंध में कौन सा युग्म सही सुमेलित है?', 'MLUPY योजना के तहत सूक्ष्म, लघु एवं मध्यम उद्योगों की स्थापना व विस्तार हेतु वित्तीय संस्थानों के माध्यम से ₹10 करोड़ तक का ऋण उपलब्ध कराया जाता है, जिसमें ₹25 लाख तक 8%, ₹5 करोड़ तक 6% और ₹10 करोड़ तक 5% का ब्याज अनुदान (Interest Subsidy) दिया जाता है।'),
('आर्टिफिशियल इंटेलिजेंस (AI) एवं डीप लर्निंग के संदर्भ में ''लार्ज लैंग्वेज मॉडल्स'' (LLMs) में प्रयुक्त ''ट्रांसफॉर्मर आर्किटेक्चर'' (Transformer Architecture) की मुख्य विशेषता क्या है?', '2017 में प्रस्तुत ''ट्रांसफॉर्मर आर्किटेक्चर'' (Attention Is All You Need) का मूल आधार सेल्फ-अटेंशन तंत्र है, जो इनपुट अनुक्रम के सभी टोकनों/शब्दों के बीच के संबंध को समानांतर (Parallel) रूप से संसाधित करता है। यही आधुनिक LLMs की रीढ़ है।'),
('भारतीय नौसेना के ''प्रोजेक्ट 75'' (Project-75) के तहत कलवरी क्लास की छह पारंपरिक डीजल-इलेक्ट्रिक स्टील्थ पनडुब्बियों का सही समूह कौन सा है?', 'प्रोजेक्ट-75 के तहत मझगांव डॉक शिपबिल्डर्स लिमिटेड (MDL) द्वारा फ्रांसीसी नौसेना समूह (Naval Group) के सहयोग से निर्मित 6 स्कॉर्पीन श्रेणी की पनडुब्बियां हैं: कलवरी, खंडेरी, करंज, वेला, वागीर और वागशीर।'),
('सेलुलर बायोलॉजी में ''माइटोकॉन्ड्रिया'' (Mitochondria) के संबंध में निम्नलिखित में से कौन सा कथन सही <strong>नहीं</strong> है?', 'माइटोकॉन्ड्रिया दोहरी झिल्ली (Double-membrane bound) वाला अर्ध-स्वायत्त कोशिकांग है। इसकी बाहरी झिल्ली छिद्रयुक्त होती है तथा आंतरिक झिल्ली अत्यधिक वलित होकर ''क्रिस्टी'' (Cristae) बनाती है।'),
('ग्लोबल वार्मिंग पोटेंशियल (GWP - 100 वर्ष के संदर्भ में) के आधार पर ग्रीनहाउस गैसों की तापन क्षमता का सही घटता क्रम कौन सा है?', '$CO_2$ का मानक GWP = 1 माना जाता है; मीथेन ($CH_4$) का GWP $\approx 28$; नाइट्रस ऑक्साइड ($N_2O$) का $\approx 265-273$; और सल्फर हेक्साफ्लोराइड ($SF_6$) का GWP सर्वाधिक $\approx 23,500$ होता है।'),
('नीचे दिए गए प्रश्न में एक कथन के उपरांत दो पूर्वधारणाएं (Assumptions) दी गई हैं:<br><br><strong>कथन:</strong> राज्य सरकार ने युवाओं को उद्योग स्थापित करने हेतु संपार्श्विक-मुक्त (Collateral-free) ऋण और ब्याज अनुदान देने की घोषणा की है।<br><br><strong>पूर्वधारणा I:</strong> कई युवा वित्तीय संसाधनों और संपार्श्विक प्रतिभूति (गारंटी) के अभाव में अपना उद्यम प्रारंभ नहीं कर पाते हैं।<br><strong>पूर्वधारणा II:</strong> राज्य में नए उद्योगों की स्थापना से स्थानीय स्तर पर रोजगार सृजन में वृद्धि होगी।', 'सरकार द्वारा योजना लाने का मूल उद्देश्य यह मानकर चलना है कि युवाओं को ऋण की बाधा है (पूर्वधारणा I) और इससे औद्योगिक विकास व रोजगार को गति मिलेगी (पूर्वधारणा II)। दोनों पूर्वधारणाएं नीतिगत निर्णय में प्रत्यक्ष रूप से अंतर्निहित हैं।'),
('छह मित्र P, Q, R, S, T और U एक पंक्ति में उत्तर की ओर मुख करके बैठे हैं। P और Q दोनों सिरों पर बैठे हैं। R, P के तुरंत दाईं ओर बैठा है। T, Q के तुरंत बाईं ओर बैठा है। S, T के बाईं ओर दूसरा है। बाएँ छोर से तीसरे स्थान पर कौन बैठा है?', 'उत्तर की ओर मुख: बायाँ छोर P और दायाँ छोर Q होगा (क्योंकि R, P के तुरंत दाईं ओर है, अतः P बाएं सिरे पर ही हो सकता है: P - R ... T - Q)। Q के तुरंत बाईं ओर T, T के बाईं ओर दूसरा S (अर्थात् P - R - U - S - T - Q)। अतः बाएं छोर से तीसरा व्यक्ति U है।'),
('A और B किसी कार्य को क्रमशः 12 दिन और 18 दिन में पूरा कर सकते हैं। वे दोनों एक साथ कार्य करना प्रारंभ करते हैं, लेकिन कार्य समाप्त होने से 3 दिन पहले A कार्य छोड़ देता है। संपूर्ण कार्य को पूरा होने में कुल कितने दिन लगेंगे?', 'माना कुल कार्य (LCM of 12, 18) = 36 यूनिट। A की क्षमता = 3 यूनिट/दिन, B की क्षमता = 2 यूनिट/दिन। अंतिम 3 दिन केवल B ने कार्य किया = $3 \times 2 = 6$ यूनिट। शेष 30 यूनिट दोनों ने मिलकर किए = $\frac{30}{3+2} = 6$ दिन। कुल समय = $6 + 3 = 9$ दिन।'),
('यदि एक समचतुर्भुज (Rhombus) के दो विकर्णों की लंबाइयां क्रमशः 16 सेमी और 12 सेमी हैं, तो उस समचतुर्भुज का परिमाप (Perimeter) क्या होगा?', 'समचतुर्भुज के विकर्ण एक दूसरे को समकोण पर समद्विभाजित करते हैं। अर्ध-विकर्ण = 8 सेमी और 6 सेमी। समकोण त्रिभुज से भुजा $a = \sqrt{8^2 + 6^2} = \sqrt{64 + 36} = \sqrt{100} = 10$ सेमी। परिमाप = $4 \times a = 4 \times 10 = 40$ सेमी।'),
('शब्द ''RAJASTHAN'' के सभी अक्षरों का प्रयोग करके कितने अलग-अलग शब्द बनाए जा सकते हैं ताकि तीनों ''A'' हमेशा एक साथ रहें?', 'शब्द ''RAJASTHAN'' में कुल 9 अक्षर हैं: R-1, J-1, S-1, T-1, H-1, N-1 और A-3। तीनों ''A'' को एक इकाई (AAA) मानने पर कुल तत्व = 7 ($R, J, S, T, H, N, [AAA]$)। इन 7 तत्वों के क्रमचय = $7! = 5040$। (चूँकि तीनों ''A'' समरूप हैं, उन्हें आपस में व्यवस्थित करने का केवल 1 तरीका है)। अतः कुल शब्द = $5040$।'),
('राजस्थान के प्रजामंडल आंदोलनों एवं उनसे जुड़े प्रमुख नेताओं के संदर्भ में निम्नलिखित युग्मों पर विचार कीजिए:<br><br>1. मारवाड़ लोक परिषद (1938) : जयनारायण व्यास, रणछोड़दास गट्टानी व आनंदराज सुराणा<br>2. मेवाड़ प्रजामंडल (1938) : बलवंत सिंह मेहता (प्रथम अध्यक्ष) एवं माणिक्य लाल वर्मा<br>3. सिरोही प्रजामंडल (1939) : गोकुलभाई भट्ट<br>4. झालावाड़ प्रजामंडल (1946) : मांगीलाल भव्य एवं कन्हैयालाल मित्तल<br><br>उपर्युक्त में से कौन से युग्म सही सुमेलित हैं?', 'मारवाड़ लोक परिषद के गठन में रणछोड़दास गट्टानी प्रथम अध्यक्ष बने; मेवाड़ प्रजामंडल के संस्थापक माणिक्यलाल वर्मा एवं प्रथम अध्यक्ष बलवंत सिंह मेहता थे; सिरोही प्रजामंडल की स्थापना मुंबई में गोकुलभाई भट्ट के नेतृत्व में हुई; झालावाड़ प्रजामंडल मांगीलाल भव्य की अध्यक्षता में गठित हुआ जिसे तत्कालीन शासक हरिश्चंद्र का संरक्षण प्राप्त था।'),
('राजस्थान के रीति-रिवाज, वेशभूषा और आभूषणों के संदर्भ में निम्नलिखित कथनों में से कौन सा <strong>असत्य</strong> है?', '''चूँप'' और ''रखन'' दांतों में पहने/जड़े जाने वाले आभूषण हैं, जबकि कान के आभूषणों में ओगण्या, झेला, पीपलपत्रा, सुरलिया, टोटी आदि आते हैं। चोंप (नाक) तथा चूँप (दांत) में अंतर ध्यान रखना आवश्यक है।'),
('गुप्तकालीन प्रशासनिक एवं सामाजिक शब्दावली के संदर्भ में सूची-I को सूची-II से सुमेलित कीजिए:<br><br><table style=''width:100%; border-collapse: collapse; margin-top:5px;'' border=''1''><tr><th>सूची-I (अधिकारी/कर)</th><th>सूची-II (कार्य/परिभाषा)</th></tr><tr><td>A. महाक्षपटलिक</td><td>i. अभिलेख विभाग व राज्य दस्तावेजों का प्रधान</td></tr><tr><td>B. संधि-विग्रहिक</td><td>ii. युद्ध एवं शांति का मंत्री</td></tr><tr><td>C. उद्रंग</td><td>iii. स्थायी कृषकों पर लगाया जाने वाला भू-राजस्व कर</td></tr><tr><td>D. विष्टि</td><td>iv. बेगार / निःशुल्क अनिवार्य श्रम</td></tr></table>', 'गुप्तकाल में महाक्षपटलिक रिकॉर्ड-कीपर/अभिलेख प्रमुख था; संधिविग्रहिक विदेश/युद्ध मंत्री था (हरिषेण इस पद पर था); उद्रंग स्थायी काश्तकारों पर भू-कर था और विष्टि बेगार प्रथा को कहा जाता था।'),
('1946 के ''कैबिनेट मिशन'' (Cabinet Mission) के प्रस्तावों के संदर्भ में निम्नलिखित में से कौन सा प्रावधान शामिल <strong>नहीं</strong> था?', 'कैबिनेट मिशन (पेथिक लॉरेंस, स्टैफोर्ड क्रिप्स, ए.वी. अलेक्जेंडर) ने संप्रभु पाकिस्तान की मांग को स्पष्ट रूप से खारिज कर दिया था। इसके स्थान पर सीमित शक्तियों वाला केंद्र और प्रांतों के त्रि-स्तरीय समूहन (Grouping) का प्रस्ताव रखा गया था।'),
('विश्व के प्रमुख घास के मैदानों (Grasslands) एवं उनकी भौगोलिक स्थिति का कौन सा युग्म सही सुमेलित <strong>नहीं</strong> है?', 'डाउन्स (Downs) ऑस्ट्रेलिया के शीतोष्ण कटिबंधीय घास के मैदान हैं। ब्राजील के उष्णकटिबंधीय घास के मैदानों को ''कंपोस'' (Campos) तथा वेनेजुएला/कोलंबिया में इन्हें ''लानोस'' (Llanos) कहा जाता है।'),
('भारत में ''राष्ट्रीय जलमार्ग'' (National Waterways) के संदर्भ में निम्नलिखित में से कौन सा युग्म सुमेलित <strong>नहीं</strong> है?', 'राष्ट्रीय जलमार्ग-4 (NW-4) गोदावरी-कृष्णा नदी प्रणाली और काकीनाडा-पुडुचेरी नहर विस्तार पर है। महानदी, ब्राह्मणी और पूर्वी तटीय नहर प्रणाली राष्ट्रीय जलमार्ग-5 (NW-5) के अंतर्गत आती है।'),
('भारतीय संविधान के अनुच्छेद 148 से 151 के अंतर्गत ''भारत के नियंत्रक एवं महालेखापरीक्षक'' (CAG) के संदर्भ में कौन सा कथन सत्य है?', 'कैग का वेतन व पेंशन भारत की संचित निधि पर भारित होता है। संविधान के अनुच्छेद 148(4) के अनुसार पदमुक्ति के बाद कैग सरकार के अधीन कोई अन्य पद धारण नहीं कर सकता। कैग अपनी रिपोर्ट राष्ट्रपति/राज्यपाल को सौंपता है जो इसे संसद/विधानमंडल में रखवाते हैं।'),
('राजस्थान में ''राज्य निर्वाचन आयोग'' (State Election Commission) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. यह अनुच्छेद 243-K के तहत एक एकल-सदस्यीय संवैधानिक आयोग है जिसकी अध्यक्षता राज्य निर्वाचन आयुक्त करता है।<br>B. राज्य निर्वाचन आयुक्त को उच्च न्यायालय के न्यायाधीश को हटाने की प्रक्रिया और आधारों पर ही हटाया जा सकता है।<br>C. यह आयोग राजस्थान में पंचायती राज संस्थाओं, नगरपालिकाओं एवं राज्य विधानसभा के चुनावों का संचालन करता है।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'राज्य निर्वाचन आयोग केवल पंचायती राज संस्थाओं और शहरी स्थानीय निकायों (नगरपालिकाओं) के चुनावों का संचालन करता है। राज्य विधानसभा और संसद के चुनावों का संचालन ''भारत निर्वाचन आयोग'' (ECI - अनुच्छेद 324) द्वारा किया जाता है।'),
('उच्च न्यायालय के ''रिट क्षेत्राधिकार'' (अनुच्छेद 226) और सर्वोच्च न्यायालय के रिट क्षेत्राधिकार (अनुच्छेद 32) की तुलना में कौन सा कथन सही है?', 'उच्च न्यायालय का रिट क्षेत्राधिकार (अनुच्छेद 226) सर्वोच्च न्यायालय (अनुच्छेद 32) की तुलना में व्यापक है क्योंकि SC केवल मूल अधिकारों (Part III) के लिए रिट जारी कर सकता है, जबकि HC मूल अधिकारों के अतिरिक्त सामान्य कानूनी अधिकारों (''any other purpose'') के लिए भी रिट जारी कर सकता है।'),
('राजकोषीय नीति के अंतर्गत ''प्राथमिक घाटा'' (Primary Deficit) की सही परिभाषा क्या है?', 'प्राथमिक घाटा = राजकोषीय घाटा − पूर्व में लिए गए ऋणों पर दिया जाने वाला ब्याज भुगतान। यह दर्शाता है कि सरकार को ब्याज देनदारियों को छोड़कर चालू वर्ष के खर्चों को पूरा करने के लिए कितनी शुद्ध उधारी की आवश्यकता है।'),
('राजस्थान में सौर ऊर्जा उत्पादन और नीतिगत पहलों के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. नवीन एवं नवीकरणीय ऊर्जा मंत्रालय (MNRE) के अनुसार राजस्थान देश में स्थापित सौर ऊर्जा क्षमता में प्रथम स्थान पर है।<br>B. भड़ला सोलर पार्क (जोधपुर/फलौदी) विश्व के सबसे बड़े एकल-स्थान सोलर पार्कों में से एक है जिसकी कुल क्षमता 2245 मेगावाट है।<br>C. राजस्थान सौर ऊर्जा नीति, 2019 के अंतर्गत वर्ष 2024-25 तक 30,000 मेगावाट क्षमता का लक्ष्य रखा गया था।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'राजस्थान देश में सौर ऊर्जा उत्पादन में शीर्ष स्थान पर है। भड़ला सोलर पार्क (4 चरणों में कुल 2245 MW) विश्व के बड़े पार्कों में शामिल है। राज्य की सौर नीति-2019 में 30 GW (30,000 MW) का महत्वाकांक्षी लक्ष्य तय किया गया था।'),
('सूचना एवं संचार प्रौद्योगिकी (ICT) में ''ब्लॉकचेन तकनीक'' (Blockchain Technology) की मूलभूत विशेषताओं में क्या शामिल <strong>नहीं</strong> है?', 'ब्लॉकचेन एक विकेंद्रीकृत (Decentralized) एवं पीयर-टू-पीयर (P2P) तकनीक है। इसमें किसी एकल केंद्रीयकृत सत्ता (Single Central Authority) का नियंत्रण नहीं होता, बल्कि नेटवर्क के सभी सहभागी नोड्स सर्वसम्मति तंत्र द्वारा डेटा को सत्यापित करते हैं।'),
('रोबोटिक्स और अंतरिक्ष अन्वेषण में प्रयुक्त ''व्योममित्र'' (Vyommitra) के संदर्भ में कौन सा कथन सही है?', 'व्योममित्र (Vyommitra) इसरो द्वारा विकसित एक हाफ-ह्यूमनॉइड रोबोट है जो अंतरिक्ष यात्रियों जैसे कार्यों की नकल कर सकता है और भारत के गगनयान मिशन के मानवरहित परीक्षणों में माइक्रोग्रैविटी व जीवन रक्षक प्रणालियों की निगरानी हेतु भेजा जा रहा है।'),
('मानव शरीर में अंतःस्रावी ग्रंथियों (Endocrine Glands) और उनके द्वारा स्रावित हार्मोन के संदर्भ में कौन सा युग्म सुमेलित <strong>नहीं</strong> है?', 'मेलाटोनिन हार्मोन ''पीनियल ग्रंथि'' (Pineal Gland) द्वारा स्रावित होता है जो हमारे शरीर की 24-घंटे की दैनिक लय (Circadian Rhythm/नींद-जागने का चक्र) को नियंत्रित करता है। थायरॉइड ग्रंथि थायरोक्सिन (T4), ट्राईआयोडोथायरोनिन (T3) और कैल्सीटोनिन स्रावित करती है।'),
('पर्यावरण संरक्षण के संदर्भ में ''इकोटोन'' (Ecotone) और ''कोर प्रभाव'' (Edge Effect) की सही संकल्पना क्या है?', 'इकोटोन (जैसे मैंग्रोव, आर्द्रभूमि, घास-वन सीमा) दो पारिस्थितिक तंत्रों का संगम/संक्रमण क्षेत्र होता है। इस सीमांत क्षेत्र में दोनों तंत्रों की प्रजातियां मिलने से विविधता बढ़ जाती है जिसे ''एज इफेक्ट'' (Edge Effect) कहा जाता है।'),
('नीचे दिए गए कथन और दो कार्यवाहियों पर विचार कीजिए:<br><br><strong>कथन:</strong> राज्य के कई सरकारी विद्यालयों में विज्ञान और गणित के शिक्षकों के पद लंबे समय से रिक्त होने के कारण छात्रों के परीक्षा परिणामों में भारी गिरावट आई है।<br><br><strong>कार्यवाही I:</strong> शिक्षा विभाग को तत्काल प्रभाव से विद्या संबल या अन्य संविदा योजनाओं के माध्यम से योग्य अतिथि शिक्षकों की अस्थायी नियुक्ति करनी चाहिए।<br><strong>कार्यवाही II:</strong> भर्ती आयोग को इन रिक्त पदों हेतु नियमित भर्ती प्रक्रिया को समयबद्ध एवं त्वरित रूप से पूरा करना चाहिए।', 'छात्रों के शैक्षणिक नुकसान को तुरंत रोकने के लिए अल्पकालिक समाधान (गेस्ट फैकल्टी - कार्यवाही I) और स्थायी समाधान हेतु नियमित भर्ती प्रक्रिया (कार्यवाही II) दोनों एक साथ उठाना प्रशासनिक रूप से सर्वाधिक उचित व व्यावहारिक कदम है।'),
('दी गई आकृति में यदि $A$, $B$ के दक्षिण में 30 मीटर है; $B$, $C$ के पश्चिम में 40 मीटर है; और $C$, $D$ के उत्तर में 30 मीटर है, तो बिंदु $A$ से बिंदु $D$ के बीच की न्यूनतम सीधी दूरी और दिशा क्या होगी?', 'निर्देशांक पद्धति में: माना B=(0,0)। तब A=(0, -30)। C, B के पूर्व में 40 मीटर है $\Rightarrow C=(40, 0)$। D, C के दक्षिण में 30 मीटर है $\Rightarrow D=(40, -30)$। A (0, -30) और D (40, -30) की y-अक्ष स्थिति समान है। अतः A से D की दूरी = $40 - 0 = 40$ मीटर और दिशा धनात्मक x-अक्ष (ठीक पूर्व) है।'),
('एक परीक्षा में 70% अभ्यर्थी अंग्रेजी में उत्तीर्ण हुए, 80% अभ्यर्थी गणित में उत्तीर्ण हुए और 10% अभ्यर्थी दोनों विषयों में अनुत्तीर्ण रहे। यदि 144 अभ्यर्थी दोनों विषयों में उत्तीर्ण हुए, तो परीक्षा में बैठने वाले कुल अभ्यर्थियों की संख्या कितनी थी?', '10% दोनों में फेल हुए $\Rightarrow$ कम से कम एक विषय में पास होने वाले = $100 - 10 = 90\%$। सूत्र: $P(A \cup B) = P(A) + P(B) - P(A \cap B) \Rightarrow 90\% = 70\% + 80\% - P(A \cap B) \Rightarrow P(A \cap B) = 150\% - 90\% = 60\%$। कुल का $60\% = 144 \Rightarrow$ कुल छात्र = $\frac{144 \times 100}{60} = 240$।'),
('एक निश्चित धनराशि 5 वर्षों में साधारण ब्याज से दोगुनी हो जाती है। समान ब्याज दर पर वह राशि कितने वर्षों में 4 गुनी (Four times) हो जाएगी?', 'दोगुनी होने पर ब्याज $SI_1 = 2P - P = P$ (समय $T_1 = 5$ वर्ष)। 4 गुनी होने पर ब्याज $SI_2 = 4P - P = 3P$। साधारण ब्याज में $SI \propto T$। अतः $\frac{P}{3P} = \frac{5}{T_2} \Rightarrow T_2 = 5 \times 3 = 15$ वर्ष।'),
('6 पुरुष और 4 महिलाएं एक गोल मेज के चारों ओर कितने प्रकार से बैठ सकते हैं ताकि कोई भी दो महिलाएं एक साथ न बैठें?', 'वृत्ताकार मेज पर पहले 6 पुरुषों को बैठाने के तरीके = $(6-1)! = 5! = 120$। 6 पुरुषों के बैठने के बाद उनके बीच 6 रिक्त स्थान (Gaps) बनेंगे। इन 6 स्थानों पर 4 महिलाओं को बैठाने के तरीके = $^6P_4 = 6 \times 5 \times 4 \times 3 = 360$। कुल अभीष्ट तरीके = $120 \times 360 = 43200$।'),
('राजस्थान खनिज नीति-2024 (Rajasthan Mineral Policy 2024) के दीर्घकालिक लक्ष्यों के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. वर्ष 2029-30 तक 50 लाख तथा वर्ष 2046-47 तक प्रत्यक्ष एवं अप्रत्यक्ष रूप से 1 करोड़ से अधिक रोजगार सृजित करना।<br>B. राज्य के सकल राज्य घरेलू उत्पाद (GSDP) में खनिज क्षेत्र के योगदान को बढ़ाकर 2029-30 तक 5% और 2046-47 तक 8% करना।<br>C. राज्य में खनिज रियायत (Mineral Concession) क्षेत्र को मौजूदा 0.68% से बढ़ाकर 2046-47 तक 2.0% तक विस्तृत करना।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'राजस्थान खनिज नीति-2024 के तहत खनन क्षेत्र का GSDP में योगदान 3.4% से बढ़ाकर 2030 तक 5% व 2047 तक 8% करने, 1 करोड़ रोजगार सृजन करने, तथा रियायत क्षेत्र को 0.68% से बढ़ाकर 2% करने का त्रि-स्तरीय लक्ष्य निर्धारित किया गया है।'),
('राजस्थान में ''सकल स्थाई पूँजी निर्माण'' (Gross Fixed Capital Formation - GFCF) में विभिन्न क्षेत्रों के योगदान का सही घटता क्रम (Descending Order) कौन सा है?', 'राजस्थान आर्थिक समीक्षा के अनुसार राज्य के सकल स्थाई पूँजी निर्माण (GFCF) में सर्वाधिक योगदान ''निर्माण'' (Construction) क्षेत्र का है, इसके पश्चात ''विनिर्माण'' (Manufacturing), फिर ''कृषि'' (Agriculture) और अंत में ''खनन'' (Mining) का स्थान आता है।'),
('राजस्थान में ''आस्था योजना'' (Aastha Scheme) के अंतर्गत विशेष सहायता एवं बीपीएल समकक्ष लाभ प्राप्त करने हेतु पात्रता की सही शर्त क्या है?', 'सामाजिक न्याय एवं अधिकारिता विभाग की ''आस्था योजना'' के तहत ऐसे परिवार जिनमें 40% या अधिक दिव्यांगता वाले विशेष योग्यजन (Persons with Disabilities) सदस्यों की संख्या 2 या उससे अधिक हो, उन्हें बिना किसी आय सीमा के बीपीएल परिवार के समकक्ष समस्त सुविधाएं दी जाती हैं।'),
('पीएम सूर्य घर मुफ्त बिजली योजना (PM Surya Ghar Muft Bijli Yojana) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>1. योजना के अंतर्गत देश भर में 1 करोड़ घरों की छतों पर रूफटॉप सोलर संयंत्र स्थापित करने का लक्ष्य है।<br>2. 2 kW तक के सिस्टम हेतु ₹30,000 प्रति kW तथा 3 kW या उससे अधिक के सिस्टम पर अधिकतम ₹78,000 की केंद्रीय वित्तीय सहायता (CFA) देय है।<br>3. योजना में पंजीकरण, तकनीकी व्यवहार्यता और सब्सिडी अंतरण की संपूर्ण प्रक्रिया नेशनल पोर्टल के माध्यम से 100% ऑनलाइन है।<br><br>उपर्युक्त में से कौन से कथन सही हैं?', 'पीएम सूर्य घर मुफ्त बिजली योजना के तहत 1 करोड़ घरों पर सोलर रूफटॉप लगाकर प्रति माह 300 यूनिट तक मुफ्त बिजली देने का लक्ष्य है। इसमें 1 kW पर ₹30,000, 2 kW पर ₹60,000 तथा 3 kW या अधिक पर ₹78,000 की तय सब्सिडी सीधे बैंक खाते में दी जाती है।'),
('राजस्थान में रीको (RIICO) द्वारा स्थापित विशिष्ट औद्योगिक पार्कों के संदर्भ में कौन सा युग्म सुमेलित <strong>नहीं</strong> है?', 'रीको द्वारा राजस्थान में 4 एग्रो फूड पार्क स्थापित किए गए हैं: (1) बोरानाडा (जोधपुर), (2) कोटा, (3) अलवर (मत्स्य इंडस्ट्रियल एरिया), और (4) श्रीगंगानगर। नैनवा (बूंदी) में एग्रो फूड पार्क नहीं है।'),
('भारत के रक्षा अनुसंधान एवं विकास संगठन (DRDO) द्वारा विकसित ''VSHORADS'' मिसाइल प्रणाली के संदर्भ में कौन सा कथन सही है?', 'VSHORADS (Very Short Range Air Defence System) DRDO के अनुसंधान केंद्र इमारत (RCI) द्वारा विकसित एक स्वदेशी 4th जनरेशन मैन-पोर्टेबल वायु रक्षा प्रणाली है जो कम दूरी व कम ऊंचाई पर उड़ने वाले दुश्मन के विमानों/ड्रोन को मार गिराने में सक्षम है।'),
('चौथी पीढ़ी के जैव ईंधन (4th Generation Biofuels) के संदर्भ में निम्नलिखित में से कौन सा स्रोत प्राथमिक रूप से उपयोग किया जाता है?', 'प्रथम पीढ़ी: खाद्य फसलें; द्वितीय पीढ़ी: गैर-खाद्य बायोमास/अपशिष्ट; तृतीय पीढ़ी: सामान्य शैवाल बायोमास; चतुर्थ पीढ़ी: आनुवंशिक रूप से संशोधित शैवाल/सूक्ष्मजीव जो उच्च लिपिड उत्पादन के साथ-साथ कार्बन डाइऑक्साइड अवशोषण (Carbon Sequestration) करते हैं।'),
('पर्यावरण एवं वायु गुणवत्ता सूचकांक (National AQI) के मानकों के अनुसार 101 से 200 के बीच की AQI सीमा को किस श्रेणी में वर्गीकृत किया गया है?', 'केंद्रीय प्रदूषण नियंत्रण बोर्ड (CPCB) के अनुसार AQI श्रेणियां: 0-50 (Good), 51-100 (Satisfactory), 101-200 (Moderate), 201-300 (Poor), 301-400 (Very Poor), और 401-500 (Severe) होती हैं।'),
('संयुक्त राष्ट्र के 17 सतत विकास लक्ष्यों (SDGs) में से कौन सा लक्ष्य विशेष रूप से ''स्थलीय पारिस्थितिक तंत्रों का संरक्षण, मरुस्थलीकरण की रोकथाम और जैव विविधता की हानि को रोकना'' (Life on Land) से संबंधित है?', 'SDG 13: जलवायु कार्यवाही (Climate Action); SDG 14: जल में जीवन (Life Below Water); SDG 15: स्थल पर जीवन (Life on Land - जैव विविधता व वनों का संरक्षण); SDG 16: शांति, न्याय और मजबूत संस्थाएं।'),
('राजस्थान में बागवानी उत्कृष्टता केंद्रों (Centres of Excellence) और संबंधित फसलों के सही सुमेलन का चयन कीजिए:<br><br><table style=''width:100%; border-collapse: collapse; margin-top:5px;'' border=''1''><tr><th>उत्कृष्टता केंद्र (स्थान)</th><th>संबंधित फसल</th></tr><tr><td>A. बस्सी (जयपुर)</td><td>i. अनार</td></tr><tr><td>B. सगरा भोजका (जैसलमेर)</td><td>ii. खजूर (Date Palm)</td></tr><tr><td>C. ढिंढोल (बस्सी/जयपुर)</td><td>iii. अनार / अमरूद</td></tr><tr><td>D. खेमरी (धौलपुर)</td><td>iv. आम (Mango)</td></tr></table>', 'सगरा भोजका (जैसलमेर) खजूर उत्कृष्टता केंद्र है; ढिंढोल (बस्सी) अनार/सब्जियों हेतु; खेमरी (धौलपुर) आम/अमरूद उत्कृष्टता केंद्र है।'),
('राष्ट्रीय कृषि एवं ग्रामीण विकास बैंक (NABARD) और ग्रामीण अवसंरचना विकास निधि (RIDF) के संदर्भ में कौन सा कथन सही है?', 'RIDF (Rural Infrastructure Development Fund) की स्थापना 1995-96 में नाबार्ड के अंतर्गत की गई थी। इसमें घरेलू वाणिज्यिक बैंकों द्वारा अपने PSL (कृषि लक्ष्य) में रह जाने वाली कमी का अंशदान जमा कराया जाता है, जिससे राज्य सरकारों को ग्रामीण बुनियादी ढांचे हेतु रियायती ऋण मिलता है।'),
('भारत के शास्त्रीय भाषाओं (Classical Languages) के दर्जे के संदर्भ में हालिया अनुमोदनों के पश्चात कुल कितनी भाषाओं को यह दर्जा प्राप्त है?', 'पूर्व में 6 भाषाएं (तमिल, संस्कृत, कन्नड़, तेलुगु, मलयालम, ओडिया) थीं। केंद्रीय मंत्रिमंडल द्वारा 5 नई भाषाओं—मराठी, पाली, प्राकृत, असमिया और बंगाली—को शास्त्रीय भाषा का दर्जा दिए जाने के बाद अब कुल शास्त्रीय भाषाओं की संख्या 11 हो गई है।'),
('हाल ही में हान्ले (लद्दाख) में उद्घाटित एशिया की सबसे बड़ी और विश्व की सबसे ऊंची इमेजिंग चेरनकोव वेधशाला ''MACE'' (Major Atmospheric Cherenkov Experiment) का विकास मुख्य रूप से किसके द्वारा किया गया है?', 'MACE दूरबीन हान्ले (लद्दाख) में 4300 मीटर की ऊंचाई पर स्थापित गामा-रे वेधशाला है। इसे BARC द्वारा ECIL और अन्य भारतीय उद्योग सहयोगियों के साथ मिलकर स्वदेशी रूप से विकसित किया गया है।'),
('राजस्थान के पुरातात्विक स्थल ''ओझियाना'' (Ojiyana) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. यह भीलवाड़ा जिले की बदनोर तहसील में कोठारी नदी बेसिन में स्थित एक ताम्रपाषाण कालीन स्थल है।<br>B. इसका उत्खनन वर्ष 2000 में बी.आर. मीणा और आलोक त्रिपाठी के निर्देशन में भारतीय पुरातत्व सर्वेक्षण द्वारा किया गया।<br>C. यहाँ से सफेद रंग से चित्रित विशिष्ट ''ओझियाना बुल'' (पकी मिट्टी का वृषभ) और गाय की मृण्मूर्तियां प्राप्त हुई हैं।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'ओझियाना (भीलवाड़ा) आहाड़-बनास संस्कृति का प्रमुख ताम्रपाषाण कालीन स्थल है। इसका उत्खनन बी.आर. मीणा और आलोक त्रिपाठी द्वारा किया गया था जहाँ से प्रसिद्ध टेराकोटा ओझियाना बुल (वृषभ) मिला है।'),
('1945 का ''एस.ए. सुधालकर प्रतिवेदन'' (S.A. Sudhalkar Report) राजस्थान की किस देशी रियासत में संवैधानिक एवं प्रशासनिक सुधारों से संबंधित है?', 'बीकानेर महाराजा सादुल सिंह के समय 1945 में संवैधानिक सुधारों और विधान परिषद की संरचना की समीक्षा हेतु बड़ौदा के पूर्व मंत्री एस.ए. सुधालकर की अध्यक्षता में एक समिति गठित की गई थी जिसने अपनी रिपोर्ट प्रस्तुत की थी।'),
('मध्यकालीन राजस्थान के ऐतिहासिक ग्रंथों एवं उनके लेखकों का कौन सा युग्म सुमेलित <strong>नहीं</strong> है?', 'खुमाण रासो के रचयिता दलपत विजय हैं। ''शत्रुशाल रासो'' डूंगरसिंह द्वारा रचित है, जबकि सूर्यमल्ल मीसण की प्रसिद्ध रचनाएं ''वंश भास्कर'' और ''वीर सतसई'' हैं।'),
('कथन और दो तर्कों पर विचार कीजिए:<br><br><strong>कथन:</strong> क्या राजस्थान के सभी शुष्क और अर्ध-शुष्क जिलों में भूजल दोहन पर तत्काल प्रभाव से सख्त कानूनी प्रतिबंध लगाया जाना चाहिए?<br><br><strong>तर्क I:</strong> हाँ, अंधाधुंध भूजल दोहन से ''डार्क जोन'' बढ़ रहे हैं और आने वाली पीढ़ियों के लिए गंभीर पेयजल संकट उत्पन्न हो सकता है।<br><strong>तर्क II:</strong> नहीं, प्रतिबंध लगाने से किसानों की आजीविका और सिंचाई आधारित कृषि उत्पादन गंभीर रूप से प्रभावित होगा जब तक कि वैकल्पिक नहरी जल उपलब्ध न कराया जाए।', 'तर्क I पर्यावरण और जल सुरक्षा के दीर्घकालिक संरक्षण का सशक्त आधार प्रस्तुत करता है, जबकि तर्क II किसानों की व्यावहारिक कृषि आजीविका और वैकल्पिक जल आपूर्ति की अनिवार्यता को दर्शाता है। नीति निर्माण के दृष्टिकोण से दोनों तर्क अत्यंत मजबूत हैं।'),
('एक वृत्त की परिधि पर समान दूरी पर 8 बिंदु स्थित हैं। इन बिंदुओं को शीर्ष मानकर कितने समकोण त्रिभुज (Right Angled Triangles) बनाए जा सकते हैं, जहाँ प्रत्येक त्रिभुज की एक भुजा वृत्त का व्यास (Diameter) हो?', '8 समदूरस्थ बिंदुओं से कुल व्यास युग्म = $8 / 2 = 4$ व्यास रेखाएं बनेंगी। अर्धवृत्त में बना कोण समकोण होता है। प्रत्येक व्यास वृत्त के शेष $8 - 2 = 6$ बिंदुओं में से प्रत्येक के साथ मिलकर एक समकोण त्रिभुज बनाएगा। अतः कुल समकोण त्रिभुज = $4 \times 6 = 24$।'),
('यदि चावल के मूल्य में 20% की कमी हो जाने से एक ग्राहक ₹1200 में 5 किलोग्राम अधिक चावल खरीद पाता है, तो चावल का घटा हुआ (वर्तमान) मूल्य प्रति किलोग्राम क्या है?', 'मूल्य में 20% की कमी = ₹1200 का 20% = ₹240। इसी ₹240 की बचत से 5 किग्रा अधिक चावल मिलता है। अतः घटा हुआ मूल्य (Reduced Price) = $\frac{240}{5} = ₹48$ प्रति किलोग्राम।'),
('एक निश्चित धनराशि पर 3 वर्ष का साधारण ब्याज ₹3,600 है (मूलधन ₹8,000 पर)। यदि समान ब्याज दर पर 2 वर्ष के लिए 8-मासिक (8-monthly) चक्रवृद्धि ब्याज की गणना की जाए, तो कुल चक्रवृद्धि ब्याज कितना होगा?', 'साधारण ब्याज की दर $R = \frac{3600 \times 100}{8000 \times 3} = 15\%$ वार्षिक। 8-मासिक संयोजन में दर $R'' = 15 \times \frac{8}{12} = 10\%$ प्रति 8-माह। 2 वर्ष (24 माह) में कुल अवधियाँ $n = \frac{24}{8} = 3$। मिश्रधन $A = 8000 \times (1 + 10/100)^3 = 8000 \times 1.331 = ₹10,648$। चक्रवृद्धि ब्याज = $10648 - 8000 = ₹2,648$।'),
('राजस्थान में ''वाल्टरकृत राजपूत हितकारिणी सभा'' के संदर्भ में निम्नलिखित में से कौन सा कथन <strong>असत्य</strong> है?', 'वाल्टरकृत राजपूत हितकारिणी सभा की स्थापना 1888 में कर्नल वाल्टर के प्रयासों से अजमेर में हुई थी। इसका उद्देश्य राजपूत और चारण समाज में विवाह, त्याग प्रथा, टीका और मृत्यु भोज (ओसर) के अत्यधिक खर्च को सीमित करना था; यह दलित सुधार सभा नहीं थी।'),
('अलवर जिले के राजोरगढ़ (पारा/नीलकंठ) में 10वीं शताब्दी के गुर्जर-प्रतिहार कालीन मंदिर निर्माण के संदर्भ में मथानदेव द्वारा निर्मित प्रसिद्ध मंदिर किस देवता को समर्पित है?', 'राजोरगढ़ (अलवर) का 959 ई. का शिलालेख गुर्जर-प्रतिहार सामंत मथानदेव (सावटा का पुत्र) से संबंधित है, जिन्होंने राजोरगढ़ में नीलकंठेश्वर महादेव (भगवान शिव) के भव्य मंदिर का निर्माण करवाया था।'),
('राजस्थान के लोक वाद्ययंत्र ''चौतारा'' (तन्दूरा) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. यह तत् (तार युक्त) वाद्ययंत्रों की श्रेणी में आता है जिसमें चार धातु के तार होते हैं।<br>B. कामड़ जाति के लोग रामदेव जी के ''तेरहताली नृत्य'' एवं भजनों के दौरान इस वाद्ययंत्र का प्रमुखता से प्रयोग करते हैं।<br>C. इसे लकड़ी की अंगूठी (मिजराब) पहनकर उंगलियों से बजाया जाता है।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'चौतारा (तन्दूरा) 4 तारों वाला तत् वाद्य है जो कामड़िया पंथ के अनुयायियों द्वारा रामदेव जी के भजनों व तेरहताली नृत्य में मिजराब की सहायता से प्रयुक्त किया जाता है।'),
('संत लालदास जी (लालदासी संप्रदाय) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. इनका जन्म मेवात क्षेत्र के धोलीदूब (अलवर) गाँव में हुआ था और इनके गुरु मुस्लिम संत गदन चिश्ती थे।<br>B. इस संप्रदाय में दीक्षा लेने वाले साधक का मुंह काला कर गधे पर उल्टा बैठाकर गाँव में घुमाया जाता है ताकि उसका अहंकार समाप्त हो सके।<br>C. संत लालदास जी की मुख्य समाधि ''शेरपुर'' (अलवर) में स्थित है और इनकी मृत्यु नगला (भरतपुर) में हुई थी।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'संत लालदास जी मेवात क्षेत्र के प्रमुख समाज-सुधारक संत थे। लालदासी संप्रदाय कठोर शारीरिक श्रम और अहंकार निवारण (गधे की सवारी) पर आधारित है। जन्म धोलीदूब, मृत्यु नगला और समाधि शेरपुर में है।'),
('राजस्थानी भाषा एवं साहित्य में प्रयुक्त होने वाले शब्द ''आड़ी'' (Aadi) और ''हीयाली'' (Hiyali) का संबंध मुख्य रूप से किससे है?', 'राजस्थानी लोक साहित्य में बुद्धि-चातुर्य व मनोरंजन हेतु पूछे जाने वाले कूट प्रश्नों एवं पहेलियों को ''आड़ी'' (अड़ी) अथवा ''हीयाली'' कहा जाता है।'),
('प्राचीन भारत में स्तूप स्थापत्य (Stupa Architecture) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. ''स्तूप'' शब्द का शाब्दिक अर्थ ''ढेर'' या ''संग्रह'' होता है और मृतकों की स्मृति में समाधि निर्माण की प्रथा बौद्ध काल से पूर्व भी प्रचलित थी।<br>B. स्तूप के अर्धगोलाकार टीले (अंड) के ऊपर एक वर्गाकार कटघरेनुमा संरचना होती है जिसे ''हर्मिका'' कहा जाता है, जो देवताओं के निवास का प्रतीक है।<br>C. सांची के महास्तूप में चारों दिशाओं में बने अलंकृत प्रवेश द्वारों को ''तोरण'' कहा जाता है।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'ऋग्वेद में भी स्तूप का उल्लेख मिलता है। अंड, हर्मिका, यष्टि, छत्र, प्रदक्षिणा पथ और तोरण द्वार स्तूप स्थापत्य के मानक अंग हैं।'),
('निम्नलिखित में से कौन से बौद्ध ग्रंथ मूल रूप से ''संस्कृत'' (Sanskrit) भाषा में रचे गए हैं?<br><br>1. दिव्यावदान (Divyavadana)<br>2. दीपवंश (Dipavamsa)<br>3. महावंश (Mahavamsa)<br>4. आर्यमंजूश्रीमूलकल्प (Aryamanjusrimulakalpa)<br><br>सही कूट का चयन कीजिए:', 'दीपवंश और महावंश श्रीलंका के प्रसिद्ध पालि (Pali) भाषा के ऐतिहासिक बौद्ध महाकाव्य हैं। दिव्यावदान और आर्यमंजूश्रीमूलकल्प महायान बौद्ध परंपरा के संस्कृत ग्रंथों में शामिल हैं।'),
('सूर साम्राज्य के शासक शेरशाह सूरी द्वारा निर्मित प्रमुख स्थापत्य स्मारकों का सही समूह कौन सा है?', 'शेरशाह सूरी ने दिल्ली में किला-ए-कुहना मस्जिद और रोहतासगढ़ का किला बनवाया। सासाराम (बिहार) में एक कृत्रिम झील के मध्य स्थित शेरशाह का स्वयं का मकबरा पूर्व-मुग़ल स्थापत्य का उत्कृष्ट उदाहरण है।'),
('विजयनगर साम्राज्य के शासक कृष्णदेवराय के राजदरबार में विख्यात कवि ''मल्लनार्य'' ने ''भाव चिंता रत्न'' एवं ''वीरशैवामृत'' ग्रंथों की रचना किस भाषा में की थी?', 'कृष्णदेवराय का काल केवल तेलुगु ही नहीं अपितु कन्नड़ और संस्कृत साहित्य का भी स्वर्णकाल था। उनके समकालीन वीरशैव कवि मल्लनार्य ने ''भाव चिंता रत्न'' और ''वीरशैवामृत'' की रचना कन्नड़ भाषा में की थी।'),
('वर्ष 1952 में स्वतंत्र भारत सरकार द्वारा ''माध्यमिक शिक्षा आयोग'' (Secondary Education Commission) का गठन किसकी अध्यक्षता में किया गया था?', 'सितंबर 1952 में मद्रास विश्वविद्यालय के कुलपति डॉ. ए. लक्ष्मणस्वामी मुदालियर की अध्यक्षता में माध्यमिक शिक्षा आयोग (मुदालियर आयोग) गठित किया गया जिसने त्रि-वर्षीय माध्यमिक एवं बहुउद्देशीय विद्यालयों की अनुशंसा की थी।'),
('विश्व के प्रमुख मरुस्थलों और उनकी भौगोलिक अवस्थिति के सही कूट का चयन कीजिए:<br><br><table style=''width:100%; border-collapse: collapse; margin-top:5px;'' border=''1''><tr><th>मरुस्थल</th><th>महाद्वीप / अवस्थिति</th></tr><tr><td>A. गोबी (Gobi)</td><td>i. मध्य एशिया (मंगोलिया/चीन)</td></tr><tr><td>B. पैटागोनिया (Patagonia)</td><td>ii. दक्षिण अमेरिका (अर्जेंटीना)</td></tr><tr><td>C. ग्रेट विक्टोरिया (Great Victoria)</td><td>iii. ऑस्ट्रेलिया</td></tr><tr><td>D. कालाहारी (Kalahari)</td><td>iv. दक्षिणी अफ्रीका (बोत्सवाना/नामीबिया)</td></tr></table>', 'गोबी एशिया का शीत मरुस्थल है; पैटागोनिया अर्जेंटीना का वृष्टि-छाया शीत मरुस्थल है; ग्रेट विक्टोरिया ऑस्ट्रेलिया में है; और कालाहारी दक्षिणी अफ्रीका में बोत्सवाना-नामीबिया में विस्तृत है।'),
('भूमध्यसागरीय कृषि (Mediterranean Agriculture) की विशिष्ट विशेषताओं के संदर्भ में निम्नलिखित में से कौन सा क्षेत्र इसके अंतर्गत <strong>नहीं</strong> आता है?', 'भूमध्यसागरीय जलवायु 30° से 45° अक्षांशों के मध्य महाद्वीपों के पश्चिमी तटों (कैलिफोर्निया, मध्य चिली, दक्षिण-पश्चिम अफ्रीका, दक्षिण एवं दक्षिण-पश्चिम ऑस्ट्रेलिया) पर पाई जाती है जो खट्टे फलों व अंगूर (विटिकल्चर) की खेती हेतु प्रसिद्ध है। उत्तरी ऑस्ट्रेलिया उष्णकटिबंधीय मानसूनी क्षेत्र है।'),
('हिमालय पर्वत श्रृंखला की निम्नलिखित श्रेणियों का उत्तर से दक्षिण (North to South) की ओर सही भौगोलिक क्रम क्या है?', 'उत्तर से दक्षिण की ओर ट्रांस-हिमालय और मुख्य हिमालय श्रेणियों का सही क्रम है: कराकोरम (सर्वाधिक उत्तर) $\rightarrow$ लद्दाख $\rightarrow$ जास्कर $\rightarrow$ महान हिमालय $\rightarrow$ मध्य/पीर पंजाल $\rightarrow$ शिवालिक (दक्षिणतम)।'),
('भारत की प्रमुख नदियों एवं उनकी सहायक नदियों के संदर्भ में निम्नलिखित में से कौन सा युग्म सुमेलित <strong>नहीं</strong> है?', 'अमरावती, भवानी, हेमावती और काबिनी ''कावेरी नदी'' की प्रमुख सहायक नदियां हैं, न कि गोदावरी की। गोदावरी की सहायक नदियों में पूर्णा, प्राणहिता, इंद्रावती, मंजीरा, सबरी और वैनगंगा शामिल हैं।'),
('भारत के मानसून और जलवायु प्रतिरूप के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:<br><br>A. पश्चिमी विक्षोभ (Western Disturbances) भूमध्य सागर में उत्पन्न होने वाले शीतोष्ण कटिबंधीय चक्रवात हैं जो उत्तर-पश्चिम भारत में ''मावठ'' लाते हैं।<br>B. लौटता हुआ उत्तर-पूर्वी मानसून (Retreating Monsoon) अक्टूबर-नवंबर में तमिलनाडु के कोरोमंडल तट पर भारी वर्षा करता है।<br>C. मानसूनी प्रयोग ''MONEX'' (Monsoon Experiment) भारत और सोवियत संघ (USSR) का एक ऐतिहासिक संयुक्त अंतर्राष्ट्रीय शोध अभियान था।<br><br>उपर्युक्त में से कौन से कथन सत्य हैं?', 'तीनों कथन भौगोलिक रूप से पूर्णतः सत्य हैं। पश्चिमी विक्षोभ भूमध्यसागरीय चक्रवात हैं; उत्तर-पूर्वी मानसून तमिलनाडु तट पर वर्षा करता है; और 1979 का MONEX अनुसंधान भारत व सोवियत संघ द्वारा वैश्विक वायुमंडलीय अनुसंधान कार्यक्रम (GARP) के तहत संचालित था।'),
('''गुरु घासीदास-तमोर पिंगला टाइगर रिजर्व'' के संदर्भ में सही तथ्य की पहचान कीजिए:', 'गुरु घासीदास-तमोर पिंगला टाइगर रिजर्व छत्तीसगढ़ के उत्तरी भाग में स्थित है जिसे नवंबर 2024 में देश का 55वां (तथा क्षेत्रफल के आधार पर देश के सबसे बड़े टाइगर रिजर्व्स में से एक) अधिसूचित किया गया।'),
('साहित्य के क्षेत्र में नोबेल पुरस्कार (Nobel Prize in Literature) 2024 से सम्मानित लेखिका ''हान कांग'' (Han Kang) का संबंध किस देश से है?', 'दक्षिण कोरियाई लेखिका हान कांग (''द वेजिटेरियन'' और ''ह्यूमन एक्ट्स'' की रचयिता) को उनकी गहन काव्यात्मक गद्य रचनाओं के लिए 2024 का साहित्य नोबेल पुरस्कार प्रदान किया गया।'),
('भारत सरकार के निर्वाचन आयोग द्वारा नागरिकों एवं राजनीतिक दलों को चुनाव संबंधी अनुमतियों व निगरानी हेतु प्रदान किया गया अपग्रेडेड मोबाइल एप्लिकेशन कौन सा है?', 'भारत निर्वाचन आयोग (ECI) ने उम्मीदवारों और राजनीतिक दलों द्वारा चुनावी रैलियों, सभाओं, लाउडस्पीकर अनुमति आदि हेतु ऑनलाइन आवेदन एवं पारदर्शी ट्रैकिंग के लिए ''Suvidha 2.0'' मोबाइल ऐप लॉन्च किया है।'),
('उत्तराखंड में आयोजित ''38वें राष्ट्रीय खेल 2025'' (38th National Games) के संदर्भ में कुल कितनी खेल स्पर्धाओं (Sporting Disciplines) और प्रदर्शन स्पर्धाओं को शामिल किया गया था?', '38वें राष्ट्रीय खेलों की मेजबानी उत्तराखंड द्वारा की गई जिसमें 38 मुख्य खेल स्पर्धाएं तथा 4 प्रदर्शन खेल (कयाकिंग, कैनोइंग, योगासन आदि) सम्मिलित किए गए।'),
('राजस्थान की रियासतों में राव जैतसी (बीकानेर के शासक) ने ''राव जैतसी रो छंद'' के अनुसार 1534 ई. में किस मुग़ल/तैमूरी शहजादे को पराजित किया था?', 'बीठू सूजा कृत ''राव जैतसी रो छंद'' के अनुसार जब बाबर के पुत्र कामरान (लाहौर का सूबेदार) ने भटनेर पर अधिकार कर बीकानेर दुर्ग पर आक्रमण किया, तब 1534 ई. में राव जैतसी ने रात्रि युद्ध में कामरान की सेना को परास्त कर खदेड़ दिया था।'),
('नीचे दिए गए वेन आरेख में तीन परस्पर प्रतिच्छेदी वृत्त ''अध्यापक'', ''महिलाएं'' और ''चिकित्सक'' को दर्शाते हैं। यदि कुछ महिलाएं अध्यापक हैं, कुछ महिलाएं चिकित्सक हैं और कुछ महिलाएं अध्यापक व चिकित्सक दोनों हैं, तो कौन सा वेन संबंध सर्वाधिक उपयुक्त है?', 'एक व्यक्ति एक साथ महिला, शिक्षिका और चिकित्सक (जैसे मेडिकल कॉलेज की प्रोफेसर) हो सकती है। अतः तीनों श्रेणियां परस्पर प्रतिच्छेदी (3-Way Overlapping) होंगी।'),
('अंग्रेजी वर्णमाला के बड़े अक्षरों (A to Z) के 21 व्यंजनों (Consonants) में से कितने ऐसे व्यंजन हैं जिनके समतल दर्पण में बने प्रतिबिम्ब मूल अक्षर के बिल्कुल समान (Symmetrical) दिखाई देते हैं?', 'अंग्रेजी के 26 बड़े अक्षरों में से 11 अक्षर ऊर्ध्वाधर सममित (Symmetric in mirror) होते हैं: A, H, I, M, O, T, U, V, W, X, Y। इनमें से स्वर (Vowels) A, I, O, U हटा देने पर 7 व्यंजन बचते हैं: H, M, T, V, W, X, Y। अतः 21 व्यंजनों में से 7 समान दिखते हैं।'),
('एक परिवार में छह सदस्य A, B, C, D, E और F हैं। B, C का पति/पत्नी है। C का पुत्र A है। F, E की माता है और D, F की पुत्री है। A की पुत्री E है। परिवार में दो विवाहित जोड़े हैं। निम्नलिखित में से कौन सा संबंध निश्चित रूप से सत्य है?', 'C और B पहली पीढ़ी के विवाहित जोड़े हैं। उनका पुत्र A है। A का विवाह F से हुआ है और उनके बच्चे E (पुत्री) और D (पुत्री) हैं। अतः E निश्चित रूप से C और B की पौत्री (Granddaughter) है।'),
('100 प्रेक्षणों का माध्य (Mean) 49 ज्ञात किया गया। बाद में यह पाया गया कि तीन प्रेक्षण जिन्हें 40, 20 और 50 पढ़ा गया था, वे वास्तव में क्रमशः 60, 70 और 80 थे। सही संशोधित माध्य क्या होगा?', 'गलत प्रेक्षणों का योग = $40 + 20 + 50 = 110$। सही प्रेक्षणों का योग = $60 + 70 + 80 = 210$। कुल योग में शुद्ध अंतर = $+100$। माध्य में शुद्ध वृद्धि = $\frac{+100}{100} = +1.0$। अतः संशोधित सही माध्य = $49 + 1 = 50$।'),
('दो पासों (Dice) को एक साथ फेंका जाता है। दोनों पासों पर आने वाले अंकों का योगफल एक ''अभाज्य संख्या'' (Prime Number) होने की प्रायिकता क्या है?', 'दो पासों के कुल संभावित परिणाम = 36। संभावित अभाज्य योग = 2, 3, 5, 7, 11। योग 2: 1 तरीका; योग 3: 2 तरीके; योग 5: 4 तरीके; योग 7: 6 तरीके; योग 11: 2 तरीके। कुल अनुकूल परिणाम = $1+2+4+6+2 = 15$। प्रायिकता $P = \frac{15}{36} = \frac{5}{12}$।')
) AS v(question_text, explanation)
WHERE q.question_text = v.question_text;

-- RAS Prelims Test 1: 200 marks / 150 questions; one-third negative marking.
UPDATE public.questions q SET points = 200.0 / 150.0, negative_marks = (200.0 / 150.0) / 3 WHERE q.test_id = 'bdfdc0f0-d3e9-4e86-a095-fda4c73e2c25';

DROP FUNCTION IF EXISTS public.submit_test(UUID);
CREATE OR REPLACE FUNCTION public.submit_test(_attempt_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _user_id UUID;
  _test_id UUID;
  _score NUMERIC(12,4) := 0;
  _correct_count INTEGER := 0;
  _wrong_count INTEGER := 0;
  _unattempted_count INTEGER := 0;
BEGIN
  SELECT user_id, test_id INTO _user_id, _test_id
  FROM public.attempts
  WHERE id = _attempt_id AND status = 'in_progress';

  IF _user_id IS NULL OR _user_id <> auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized or attempt already submitted';
  END IF;

  -- Validate answer/question/option relationships and score server-side.
  SELECT
    COALESCE(SUM(CASE
      WHEN o.option_text = 'अनुत्तरित प्रश्न' THEN 0
      WHEN o.is_correct THEN q.points
      ELSE -q.negative_marks
    END), 0),
    COUNT(*) FILTER (WHERE o.option_text <> 'अनुत्तरित प्रश्न' AND o.is_correct),
    COUNT(*) FILTER (WHERE o.option_text <> 'अनुत्तरित प्रश्न' AND NOT o.is_correct)
  INTO _score, _correct_count, _wrong_count
  FROM public.attempt_answers aa
  JOIN public.questions q ON q.id = aa.question_id AND q.test_id = _test_id
  JOIN public.options o ON o.id = aa.chosen_option_id AND o.question_id = q.id
  WHERE aa.attempt_id = _attempt_id;

  SELECT COUNT(*) INTO _unattempted_count
  FROM public.questions q
  WHERE q.test_id = _test_id
    AND NOT EXISTS (
      SELECT 1 FROM public.attempt_answers aa
      JOIN public.options o ON o.id = aa.chosen_option_id
      WHERE aa.attempt_id = _attempt_id
        AND aa.question_id = q.id
        AND o.question_id = q.id
        AND o.option_text <> 'अनुत्तरित प्रश्न'
    );

  UPDATE public.attempts
  SET status = 'completed', finished_at = now(), score = _score
  WHERE id = _attempt_id;

  RETURN jsonb_build_object(
    'score', _score,
    'correct', _correct_count,
    'wrong', _wrong_count,
    'unattempted', _unattempted_count
  );
END;
$$;
ReVOKE EXECUTE ON FUNCTION public.submit_test(UUID) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.submit_test(UUID) TO authenticated;

DROP FUNCTION IF EXISTS public.get_test_result(UUID);
CREATE OR REPLACE FUNCTION public.get_test_result(_attempt_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _owner UUID;
  _test UUID;
  _result JSONB;
BEGIN
  SELECT user_id, test_id INTO _owner, _test
  FROM public.attempts WHERE id = _attempt_id AND status = 'completed';

  IF _owner IS NULL OR (_owner <> auth.uid() AND NOT public.is_admin()) THEN
    RAISE EXCEPTION 'Unauthorized or result not available';
  END IF;

  SELECT jsonb_build_object(
    'attempt', to_jsonb(a),
    'questions', COALESCE(jsonb_agg(jsonb_build_object(
      'question_id', q.id,
      'question_number', q.order_index + 1,
      'question_text', q.question_text,
      'points', q.points,
      'negative_marks', q.negative_marks,
      'explanation', q.explanation,
      'your_answer', CASE WHEN aa.id IS NULL THEN NULL ELSE yo.option_text END,
      'correct_answer', co.option_text,
      'status', CASE
        WHEN aa.id IS NULL OR yo.option_text = 'अनुत्तरित प्रश्न' THEN 'unattempted'
        WHEN yo.is_correct THEN 'correct'
        ELSE 'wrong'
      END
    ) ORDER BY q.order_index), '[]'::jsonb)
  ) INTO _result
  FROM public.attempts a
  JOIN public.questions q ON q.test_id = a.test_id
  LEFT JOIN public.attempt_answers aa ON aa.attempt_id = a.id AND aa.question_id = q.id
  LEFT JOIN public.options yo ON yo.id = aa.chosen_option_id
  LEFT JOIN public.options co ON co.question_id = q.id AND co.is_correct = true
  WHERE a.id = _attempt_id;

  RETURN _result;
END;
$$;
ReVOKE EXECUTE ON FUNCTION public.get_test_result(UUID) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.get_test_result(UUID) TO authenticated;
